INSERT INTO `ulasan` (`id`, `teks_asli`, `teks_clean`, `label`, `tipe_data`, `tanggal_input`) VALUES
(1, 'Salah satu pantai terpopuler yg ada di Provinsi Kalsel. Pantai yg selalu menjadi tujuan wisata dari daerah Kalsel dan sekitarnya. Pantainya lumayan enak, rame, banyak orang jualan, banyak gazebo untuk sekadar beristirahat dan banyak juga menyediakan penginapan untuk yg pengen menikmati suasana pantai yg lebih lama. Pantai ini sangat kids-friendly, karena ombaknya yg tidak terlalu besar. Pasir pantainya bukan tipe pasir pantai yg putih, maklum karena daerah di Kalimantan banyak daerah rawa-rawa dan sungai, jadi jarang ada pantai yg berpasir putih. Selain itu, banyak aktivitas yg menyenangkan yg bisa dilakukan di sini seperti naik banana boat, main ATV, naik perahu nyebrang ke pulau seberangnya atau berenang.', 'salah satu pantai populer yang ada provinsi kalsel pantai yang jadi tuju dari daerah kalsel pantai lumayan enak rame banyak orang jual banyak gazebo sekadar istirahat banyak juga sedia inap yang ingin nikmat suasana pantai yang lebih lama pantai sangat kids friendly karena ombak yang tidak_terlalu besar pasir pantai bukan_tipe pasir pantai yang putih maklum karena daerah kalimantan banyak daerah rawa rawa sungai jadi jarang ada pantai yang pasir putih itu banyak aktivitas yang senang yang bisa laku seperti naik banana main atv naik perahu nyebrang ke pulau seberang renang', 'negatif', 'latih', '2026-04-27 22:52:46'),
(2, 'Akses ke lokasi wisata sudah bagus, tempatnya nyaman, banyak dari warga menyediakan tempat mandi ataupun WC jadi aman untuk pengunjung. Selain tempat inap dari pengelola baik berupa fila, atau tenda2 berbagai ukuran dari warga juga banyak berjejer penginapan untuk disewakan. Sayang kebersihan pantai kurang.', 'akses ke lokasi sudah bagus nyaman banyak dari warga sedia mandi wc jadi aman inap dari kelola baik upa fila ukur dari warga juga banyak jejer inap sayang bersih pantai kurang', 'positif', 'uji', '2026-04-27 22:52:46'),
(3, 'Mirip Takisung, Eksplor ke Pulau Datu untuk Air yang Jernih Pantai Batakan Baru secara umum memiliki karakteristik yang mirip dengan Pantai Takisung. Pantai utama sendiri tidak saya rekomendasikan untuk mandi atau berenang karena airnya berwarna coklat dan cukup keruh akibat dari lumpur. Namun, daya tarik utama justru ada di Pulau Datu yang ada di seberang. Untuk menyeberang, kita bisa menyewa kapal dengan harga yang sangat terjangkau, yaitu Rp 20.000 per orang. Air di sekitar Pulau Datu jauh lebih jernih dan cocok untuk berenang. Hati-hati dengan karang di sekitar pulau yang cukup tajam, disarankan memakai sepatu air untuk keamanan. Di pantai utama, tersedia wahana air seperti Banana Boat dan Donat Boat dengan harga yang sangat murah, hanya Rp 20.000/orang. Selain itu, ada juga ATV (All-Terrain Vehicle) yang bisa disewa dengan harga Rp 50.000 untuk 20 menit. Fasilitas pendukung seperti penginapan dan rumah makan sangat banyak tersedia di sekitar kawasan ini, jadi tidak perlu khawatir untuk menginap atau mencari kuliner. Kesimpulan: Pantai ini cocok untuk bersantai dan mencoba wahana air yang murah, tapi jika ingin berenang, wajib untuk menyeberang ke Pulau Datu.', 'mirip takisung eksplor ke pulau datu air yang jernih pantai umum milik karakteristik yang mirip pantai takisung pantai utama sendiri tidak_saya rekomendasi mandi renang karena air warna keruh cukup keruh akibat dari lumpur daya tarik utama ada pulau datu yang ada seberang seberang bisa kapal harga yang sangat jangkau rp orang air pulau datu jauh lebih jernih cocok renang hati hati karang pulau yang cukup tajam saran pakai sepatu air aman pantai utama sedia air seperti banana donat harga yang sangat murah hanya rp orang itu ada juga atv all terrain vehicle yang bisa harga rp menit fasilitas dukung seperti inap rumah makan sangat banyak sedia kawasan jadi tidak_perlu khawatir inap cari kuliner simpul pantai cocok santa coba air yang murah ingin renang wajib seberang ke pulau datu', 'negatif', 'latih', '2026-04-27 22:52:46'),
(4, 'Tempatnya punya potensi bagus untuk wisata keluarga, tetapi kondisi kebersihannya sangat disayangkan. Sampah tidak hanya di satu titik, melainkan menyebar, bahkan ada popok di area api unggun. Semoga ke depan tersedia pengelolaan sampah yang lebih baik dan pengunjung juga lebih bertanggung jawab dengan membawa pulang sampah masing-masing.', 'punya potensi bagus keluarga kondisi bersih sangat sayang sampah tidak_hanya satu titik lain sebar ada popok api unggun moga ke sedia kelola sampah yang lebih baik juga lebih tanggung jawab bawa pulang sampah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(5, 'Pantainya bagus di beberapa spot tertentu. Namun karena banyaknya tenda2 jadi terlihat agak kurang rapi', 'pantai bagus spot tentu karena banyak jadi lihat agak kurang_rapi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(6, 'Terakhir kali datang kesini deh kayaknya. Pantai udah kayak pengungsian karna banyak tenda dan gajebo yang disewakan warga lokal ga beraturan di bawah pohon pohon pinusnya.', 'kali datang ke sini saja kayak pantai sudah seperti ungsi karena banyak gajebo yang warga lokal tidak_atur bawah pohon pohon pinus', 'negatif', 'latih', '2026-04-27 22:52:46'),
(7, 'Salah satu pantai yang ada di Kabupaten Tanah Laut. Akses jalan menuju pantai bagus. Biaya masuk dihitung perorang dewasa dan biaya parkir kendaraan. pantai cukup panjang dengan air yang agak kecoklatan dan pasir becampur cangkang kerang. sehingga kada ada rasa sakit di kaki jika terinjak. Terdapat banyak permainan yang disediakan oleh swadaya masyarakat sekitar seperti motor ATV, banana boat, serta ada kapal/klotok untuk yang ingin menuju ke pulau datu. Banyak juga tempat makanan, oleh-oleh serta penyewaan kamar mandi dan toilet. Di sekitaran pantai ada banyak tenda yang disewakan, bisa untuk menginap. Saat menginap ditenda disarankan datang saat sore hari. Malam hari kadang banyak tenda lain yang karokean, jd saat istirahat malam bisa terganggu. Saat pagi hari mulai jam 7, tenda sudah tidak dapat ditempati karena sangat panas dan kebanyakan hanya disediakan kipas angin. Catatan penting bagi warga dan pengunjung adalah terkait sampah. Banyak sampah yang bertebaran disekitar pantai. namun sangat sedikit tempat sampah yang disediakan. Jadi perlu kesadaran masing-masing untuk menjaga kebersihan di area pantai.', 'salah satu pantai yang ada kabupaten tanah laut akses jalan tuju pantai bagus biaya masuk hitung orang dewasa biaya parkir kendara pantai cukup panjang air yang agak coklat pasir becampur cangkang kerang tidak_ada sakit kaki injak dapat banyak main yang sedia swadaya masyarakat seperti motor atv banana serta ada kapal perahu yang ingin tuju ke pulau datu banyak juga makan serta kamar mandi toilet pantai ada banyak yang bisa inap inap saran datang sore malam kadang banyak lain yang karokean jadi istirahat malam bisa ganggu pagi mulai jam sudah tidak_dapat karena sangat panas banyak hanya sedia kipas angin catat penting bagi warga kait sampah banyak sampah yang tebar pantai sangat sedikit sampah yang sedia jadi perlu sadar jaga bersih pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(8, 'Pantai paling dekat di daerah kalsel, intinya saja pantai ini sangat kotor, kotor yang saya maksud yaitu sampah yang berceceran di tepian dari ujung ke ujung, kita hanya bisa bermain di tepian saja, saya tidak menyarankan untuk mandi karena pasirnya bercampur lumpur, dan usahakan tetap memakai alas kaki, untuk semuanya mohon jangan buang sampah sembarangan demi menjaga kelestarian alam, terima kasih.', 'pantai dekat daerah kalsel inti saja pantai sangat kotor kotor yang saya maksud sampah yang cecer tepi dari ujung ke ujung hanya bisa main tepi saja saya tidak_saran mandi karena pasir campur lumpur usaha tetap pakai alas kaki semua mohon jangan_buang sampah sembarang jaga lestari alam terima kasih', 'negatif', 'latih', '2026-04-27 22:52:46'),
(9, 'Menurut sy pantai batakan skrg sulit untuk dpt tempat free krn banyakny tenda tenda + sejenis bungalow yg di sewakan. Sy sebagai pengunjung yg biasa bawa keluarga + santai bawa bekal dr rumah + tikar seadanya agk kurang srek 🙏 (kaum mendang mending mon mf) Parkir mobil 5k + 10k perorg dewasa. Tp kdg adalg oknum di dlm yg minta parkir mobil lg pdhl sdh bayar di loket pintu masuk dpn. Juni2025, pantai ny terpantau kotor ya.. pdhl kykny diambil alih dinas gt perawatanny 🙏 sy ktmu 3-4 buah sampah popok dibibir pantai. Blm lg tumpukan samping pohon & sekitarny. Agk miris sm pengunjung tp pengelola jg mmg kurang menyediakan tmpt sampah kykny ya. Semoga ke depanny makin baik.', 'turut saya pantai sulit dapat free karena banyakny jenis bungalow yang saya yang biasa bawa keluarga santai bawa bekal dari rumah tikar ada agk kurang_cocok kaum dang mending mon mf parkir mobil k k perorg dewasa kdg adalg oknum dalam yang minta parkir mobil lagi sudah bayar loket pintu masuk dpn juni pantai ny pantau kotor ya seperti ambil alih dinas gt perawatanny saya ktmu buah sampah popok bibir pantai belum_lagi tumpu samping pohon sekitarny agk miris sama kelola juga mmg kurang_sedia tmpt sampah seperti ya moga ke depanny makin baik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(10, 'Parkir luas, pantai luas, pasir putih, banyak wahana, banyak tempat makan/istirahat.', 'parkir luas pantai luas pasir putih banyak banyak makan istirahat', 'negatif', 'latih', '2026-04-27 22:52:46'),
(11, 'Pantai batakan memiliki fasilitas wisata yang modern saat ini, banyak tenda camping maupun villa untuk menginap disekitar pantai. wahana atv dan banana boat juga tersedia untuk bersenang-senang bersama keluarga maupun teman-teman. plus langit sunsetnya juga cantik', 'pantai milik fasilitas yang modern banyak camping villa inap pantai atv banana juga sedia senang senang sama keluarga teman teman plus langit sunset juga cantik', 'positif', 'latih', '2026-04-27 22:52:46'),
(12, 'Merasakan sensasi bermalam ditepi pantai Batakan baru....', 'rasa sensasi malam tepi pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(13, 'Beberapa kali sering ke pantai ini. emang karena nyaman aja tempatnya. tiket masuk juga terjangkau. banyak tempat untuk pikniknya juga mungkin nanti di daerah sana lebih banyak menyewakan alat kulineran saja seperti grill dan sejenisnya. soalnya di sini yang agak kurang menariknya.... dari segi kuliner saja. tapi kalau oleh olehnya sudah terbilang oke... apalagi ada ikan asin khas sana juga...🥰', 'kali sering ke pantai memang karena nyaman saja tiket masuk juga jangkau banyak piknik juga mungkin nanti daerah lebih banyak alat kuliner saja seperti grill jenis soal yang agak kurang_tarik dari segi kuliner saja kalau sudah bilang oke ada ikan asin khas juga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(14, 'Saya menilai dari bising nya waktu malam saat jam istirahat, banyak nya kendaraan bermotor yg menggunakan knalpot blong/brong lalu lalang. Pihak keamanan pantai ataupun dari pemerintah harus menertibkan ini. Karena saya selaku pengunjung merasa terganggu krn membawa anak kecil saat menginap. Adapun aturan membunyikan soundsystem saat tengah malam (kecuali ada event/acara), diluar daripada itu semestinya berlakukan jam malam aturan membunyikan soundsystem. Untuk layanan kamar dan parkiran saya nilai cukup bagus.. Terima kasih', 'saya nilai dari berisik waktu malam jam istirahat banyak kendara motor yang guna knalpot blong brong lalu lalang pihak aman pantai dari perintah harus tertib karena saya rasa ganggu karena bawa anak kecil inap atur bunyi soundsystem tengah malam kecuali ada event acara luar itu mesti laku jam malam atur bunyi soundsystem layan kamar parkir saya nilai cukup bagus terima kasih', 'negatif', 'latih', '2026-04-27 22:52:46'),
(15, 'Salah satu objek wisata unggualan di tanah laut yang semakin berbenah, sebelum sampai batakan banyak pilihan wisata hiking, tracking yang bisa menjadi alternatif', 'salah satu objek unggualan tanah laut yang makin benah belum sampai banyak pilih hiking tracking yang bisa jadi alternatif', 'negatif', 'latih', '2026-04-27 22:52:46'),
(16, 'Pantai yang worth it untuk dikunjungi walau cukup jauh ditambah dengan adanya dermaga kecil dengan penerangan bertenaga surya kalau malam dan cocok buat foto² serta bisa menyewa tukang foto dan disini juga banyak penginapan. Untuk sampah masih banyak berserakan entah dibibir pantai maupun disekitar dermaga', 'pantai yang padan it kunjung walau cukup jauh tambah ada dermaga kecil terang tenaga surya kalau malam cocok buat foto serta bisa tukang foto di sini juga banyak inap sampah banyak sera entah bibir pantai dermaga', 'negatif', 'uji', '2026-04-27 22:52:46'),
(17, 'Pantainya lumayan rame...byk penginapan dan tenda sewaan utk acara keluarga atau kantor. Ada banana boat... atv dll.', 'pantai lumayan rame banyak inap acara keluarga kantor ada banana atv dan lain', 'positif', 'latih', '2026-04-27 22:52:46'),
(18, 'Sangat indah dan lumayan bersih, walau ada sedikit sampah yg berserakan, tolong untuk pengunjung, buang sampah jgn sembarangan, karena tempat sampah saya lihat sdh begitu bnyak di sediakan...', 'sangat indah lumayan bersih walau ada sedikit sampah yang sera tolong buang sampah jangan_sembarang karena sampah saya lihat sudah begitu banyak sedia', 'negatif', 'latih', '2026-04-27 22:52:46'),
(19, 'Kok karcisnyaa duaa yaa? di karcis bilang 9rb di bilang 10 rb dan karcis motor 5rb satu org 15rb? dan banyak nyediakan gejebo &camping sepanjang pantai tolong ditindak lanjuti ,dan banyak sampah juga', 'kok karcis dua ya karcis bilang ribu bilang ribu karcis motor ribu satu orang ribu banyak sedia gazebo camping panjang pantai tolong tindak lanjut banyak sampah juga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(20, 'Pantainya semakin bagus dikelola, cukup menyenangkan bermain air disini. Ada wahana kuda, ATV, banana boat, dll. Penginapan sangat banyak tersedia disini, jadi tidak perlu khawatir kekurangan kamar', 'pantai makin bagus kelola cukup senang main air di sini ada kuda atv banana dan lain inap sangat banyak sedia di sini jadi tidak_perlu khawatir kurang kamar', 'negatif', 'latih', '2026-04-27 22:52:46'),
(21, 'Pantai sudah bagus dan terawat kebersihan nya,toilet,kamar mandi ,penginapan & warung tersedia banyak.cuma gasan ulun terlalu banyak gazebo berbayar', 'pantai sudah bagus awat bersih toilet kamar mandi inap warung sedia banyak hanya gas saya terlalu banyak gazebo bayar', 'netral', 'uji', '2026-04-27 22:52:46'),
(22, 'Bisa menikmati pemandangan sunset dan sunrise di Pantai ini. Disekitar area pantai banyak terdapat penginapan dan warung orang berjualan makanan, souvenir dan oleh-oleh 👍🏻', 'bisa nikmat pandang sunset sunrise pantai pantai banyak dapat inap warung orang jual makan souvenir', 'positif', 'latih', '2026-04-27 22:52:46'),
(23, 'Pantai Batakan, yang terletak di Kecamatan Panyipatan, Kabupaten Tanah Laut, Provinsi Kalimantan Selatan, menawarkan pemandangan alam yang indah dan menyenangkan bagi para pengunjung. Dengan rating 5, mari kita jelajahi keindahan pantai ini lebih lanjut. Pantai Batakan dikelilingi oleh panorama pegunungan yang memukau. Saat matahari terbenam, pantai ini menawarkan pemandangan sunset yang indah. Pengunjung dapat menikmati berbagai aktivitas di sini: Keliling Pantai: Sewa ATV atau kuda untuk menjelajahi keindahan pantai. Permainan Air: Nikmati sensasi babana boat atau speedboat yang menguji adrenalin. Bermain Air: Tersedia penyewaan ban sebagai pelampung. Bermain Voli: Luasnya bibir pantai cocok untuk bermain voli atau bola plastik. Bersantai: Duduk di bawah pohon cemara sambil menikmati pemandangan pantai dan aktivitas pengunjung lainnya. Ziarah Pulau Datu: Pulau Datu, yang terletak di lepas Pantai Batakan, memiliki makam Datu Pamulutan yang menjadi obyek wisata religi. Menikmati Sunset: Tutup liburan dengan menikmati sunset yang memukau sebelum pulang ke rumah. Jarak Pantai Batakan sekitar 40 km dari Kota Banjarmasin, ibu kota provinsi, dan akses menuju pantai ini relatif baik. Semoga perjalanan Anda ke Pantai Batakan menjadi pengalaman yang tak terlupakan!', 'pantai yang letak camat panyipatan kabupaten tanah laut provinsi kalimantan selatan tawar pandang alam yang indah senang bagi para rating mari jelajah indah pantai lebih lanjut pantai keliling panorama gunung yang pukau matahari benam pantai tawar pandang sunset yang indah dapat nikmat aktivitas keliling pantai atv kuda jajah indah pantai main air nikmat sensasi babana speedboat yang uji adrenalin main air sedia ban pelampung main voli luas bibir pantai cocok main voli bola plastik santa duduk bawah pohon cemara nikmat pandang pantai aktivitas lain ziarah pulau datu pulau datu yang letak lepas pantai milik makam datu pamulutan yang jadi obyek religi nikmat sunset tutup libur nikmat sunset yang pukau belum pulang ke rumah jarak pantai km dari kota banjarmasin kota provinsi akses tuju pantai relatif baik moga jalan anda ke pantai jadi alam yang tak lupa', 'positif', 'latih', '2026-04-27 22:52:46'),
(24, 'Pantai ini cukup luas dan nyaman namun perlunya menjaga kebersihan pantai karena kotor warna menjadi coklat, dahulu dikatakan bersih dan putih pantai Nya', 'pantai cukup luas nyaman perlu jaga bersih pantai karena kotor warna jadi keruh dahulu kata bersih putih pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(25, 'Pertama kali bawa anak-anak ke pantai berujung kecewa. Wisata pantai jadi besecamp anak-anak kendaraan knalpot racing. Berisik!! Pengunjung wisata ingin suasana baru yang tenang akhirnya harus \"menikmati\" Bunyi knalpot yang terus menerus. Terlihat dari semua mimik wajah pengunjung yang lain yang juga terlihat kecewa. Semoga bisa ditanggulangi. Jujur, jera bawa anak-anak kesini.', 'kali bawa anak anak ke pantai ujung kecewa pantai jadi besecamp anak anak kendara knalpot racing berisik ingin suasana yang tenang harus nikmat bunyi knalpot yang terus terus lihat dari semua mimik wajah yang lain yang juga lihat kecewa moga bisa tanggulang jujur jera bawa anak anak ke sini', 'negatif', 'latih', '2026-04-27 22:52:46'),
(26, 'Rame, kebersihan lokasi terus di jaga. Dan mohon hati2 juga karena ada beberapa beling pecahan botol di pinggir pantai.', 'rame bersih lokasi terus jaga mohon hati juga karena ada beling pecah botol pinggir pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(27, 'Pantainya masih bisa dikembangkan lebih baik. Perlu sinergi semua pihak, khususnya Pemda Tanah Laut. Masih banyak sampah berserakan.', 'pantai bisa kembang lebih baik perlu sinergi semua pihak khusus perintah tanah laut banyak sampah sera', 'negatif', 'uji', '2026-04-27 22:52:46'),
(28, 'cukup nyaman untuk berlibur, jalan menuju lokasi bagus, harga tiket masuk murah, pantai cukup nyaman untuk menghilangkan penat. Tapi sayang waktu saya datang pas banyak sampah si sepanjang pantai mungkin terbawa saat air pasanvg. Selebih. Nya oke', 'cukup nyaman libur jalan tuju lokasi bagus harga tiket masuk murah pantai cukup nyaman hilang penat sayang waktu saya datang pas banyak sampah si panjang pantai mungkin bawa air pasanvg lebih oke', 'negatif', 'uji', '2026-04-27 22:52:46'),
(29, 'cocok buat liburan, lumayan agak jauh dari bjm tapi ok aja, sudah lumayan bersih', 'cocok buat libur lumayan agak jauh dari banjarmasin oke saja sudah lumayan bersih', 'positif', 'latih', '2026-04-27 22:52:46'),
(30, 'Ada sewa tenda cocok untuk camping, mobil ATV , trail dll', 'ada cocok camping mobil atv trail dan lain', 'netral', 'uji', '2026-04-27 22:52:46'),
(31, 'Bagus dan semakin banyak tempat penginapan nya.. Ada fotografer nya juga.. Verry good !!', 'bagus makin banyak inap ada fotografer juga verry good', 'positif', 'latih', '2026-04-27 22:52:46'),
(32, 'Sunset nya cantik banget dan pemandangannya bagus, pantainya bersih (mudah-mudahan pengunjung juga semakin sadar utk tidak membuang sampah sembarangan) Harga barang dan makanan disana juga masih masuk akal. Tidak banyak pungutan liar. Saya pingin lagi camping disana.', 'sunset cantik banget pandang bagus pantai bersih mudah mudah juga makin sadar tidak_buang sampah sembarang harga barang makan di sana juga masuk akal tidak_banyak pungut liar saya pingin lagi camping di sana', 'positif', 'uji', '2026-04-27 22:52:46'),
(33, 'Pantai Batakan Baru merupakan salah satu destinasi wisata favorit yg ada di Kabupaten Tanah Laut. Selain menyajikan keindahan alam, terdapat juga berbagai fasilitas yg mudah ditemukan seperti penginapan, kamar mandi/wc, mushola, gazebo, tempat perkemahan, dsb. Menariknya, pantai batakan baru tetap ramai dikunjungi meski bukan di hari libur. Tempat wisata ini juga terus melakukan pembangunan dan pembaharuan setiap tahunnya.', 'pantai rupa salah satu destinasi favorit yang ada kabupaten tanah laut saji indah alam dapat juga fasilitas yang mudah temu seperti inap kamar mandi wc mushola gazebo kemah dsb tarik pantai tetap ramai kunjung meski bukan_di libur juga terus laku bangun baharu', 'positif', 'uji', '2026-04-27 22:52:46'),
(34, 'Pantainya luas, banyak pilihan penginapan, banyak wahana permainan air. Biaya masuk 5 rb perorang. Sewa ATv 50rb/25 menit. Banana boat 20 ribu perorang. Sewa penginapan di sekitar pantai harga weekend 250 ribu perkamar. Ada juga sewa glamping dan camp biasa namun harus booking sebelumnya. Minus jalan utama di dalam lokasi pantai tergenang air saat hujan. Jadi agak menyulitkan untuk mobil kecil. Mohon lebih diperhatikan oleh pengelola. Rate 7/10', 'pantai luas banyak pilih inap banyak main air biaya masuk ribu orang atv ribu menit banana ribu orang inap pantai harga weekend ribu kamar ada juga glamping camp biasa harus booking belum minus jalan utama dalam lokasi pantai genang air hujan jadi agak sulit mobil kecil mohon lebih perhati kelola rate', 'negatif', 'latih', '2026-04-27 22:52:46'),
(35, 'Lumayan si buat experience pertama kali, sepertinya aku bakal sekali aja kesini soalnya untuk urusan parkir memarkir minta sama dishub buat sambil mengarahkan, karena kebetulan saya berlibiur kesini sewaktu tahun baru otomatis pengunjung membludak. Pemerintah kab tanah laut di perhatikan lagi ya, supaya tempat wisata nya teratur dan dapat pengunjung rame terus tiap tahun. Semangat!!', 'lumayan si buat experience kali seperti saya sekali saja ke sini soal urus parkir parkir minta sama dishub buat arah karena betul saya berlibiur ke sini waktu otomatis membludak perintah kab tanah laut perhati lagi ya supaya atur dapat rame terus semangat', 'negatif', 'latih', '2026-04-27 22:52:46'),
(36, 'Pantainya sejuk dan dekat dari Banjarmasin, cuma 1 sih pesan untuk para pengunjung dan juga pengelola, JAGA KEBERSIHAN, kenyamanan kita dimulai dari tidak membuang sampah sembarangan. Biasakan membawa kantong sampah sebelum berkunjung ke wisata manapun', 'pantai sejuk dekat dari banjarmasin hanya pesan para juga kelola jaga bersih nyaman mulai dari tidak_buang sampah sembarang biasa bawa kantong sampah belum kunjung ke', 'negatif', 'latih', '2026-04-27 22:52:46'),
(37, 'Pantainya bagus, cukup bersih, banyak penjual keliling, paling serunya ada kawasan khusus buat kamping n ada penyewaan alat2nya jg dengan harga 70rb aja, rame banget yg camp disini apalagi malam minggu, bukan cuma orang2 berpasangan, tapi juga orang tua dan keluarga besar, dan wahana airnya juga lengkap, seru.', 'pantai bagus cukup bersih banyak jual keliling seru ada kawasan khusus buat kamping n ada alat juga harga ribu saja rame banget yang camp di sini malam minggu bukan_hanya orang pasang juga orang tua keluarga besar air juga lengkap asik', 'positif', 'latih', '2026-04-27 22:52:46'),
(38, 'Seru sih pertama kli jalan2 jauh berdua aja😍 Banyak wahana2 jga', 'asik kli jalan jauh dua saja banyak juga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(39, 'Pantainya bersih, luas, nyaman. Bisa leluasa menikmati pantai. Wahananya juga banyak. Ada ATV, kuda, banana boat. Penyewaan tempat juga ada kya kursi, tenda. Cuma kurang tau harganya. Untuk tiket masuk tergolong murah. Berdua dengan 1 sepeda motor bayar 11rb.', 'pantai bersih luas nyaman bisa leluasa nikmat pantai juga banyak ada atv kuda banana juga ada kya kursi hanya kurang_tau harga tiket masuk golong murah dua sepeda motor bayar ribu', 'positif', 'latih', '2026-04-27 22:52:46'),
(40, 'Efek pasang dan sering hujan di sepanjang desember membuat banyak sampah- sampah yang terbawa ke pantai dan membuat lokasinya terlihat jorok karena sepertinya tak ada perawatan maupun pembersihan area pantai. Di area garis pantai hampir seluruh area yang terbuka untuk wisatanya banyak sampah plastik. Keuntungan tempat ini dibandingkan batakan lama adalah adanya spot foto yang di atur sedemikian rupa dan terlihat fotoable dan juga ada penyewaan tenda buat camping', 'efek pasang sering hujan panjang desember buat banyak sampah sampah yang bawa ke pantai buat lokasi lihat kotor karena seperti tak ada awat bersih pantai garis pantai yang buka banyak sampah plastik untung banding lama ada spot foto yang atur rupa lihat fotoable juga ada buat camping', 'positif', 'uji', '2026-04-27 22:52:46'),
(41, 'Pantai Batakan Baru, salah satu destinasi wisata bahari yang terletak di Kalimantan Selatan, menyimpan keindahan alam yang sejatinya mampu memikat hati para pengunjung. Dengan garis pantai yang memanjang, deburan ombak yang menenangkan, serta pohon-pohon cemara di kejauhan, pantai ini menjadi salah satu lokasi wisata favorit bagi masyarakat sekitar. Namun, di balik potensi keindahannya, masalah besar tengah menggerogoti daya tarik pantai ini: sampah. Gambar di atas menunjukkan kondisi memprihatinkan di Pantai Batakan Baru. Hamparan pasir yang seharusnya bersih dan memanjakan mata kini tertutup oleh tumpukan sampah plastik, kayu-kayu bekas, hingga limbah lainnya yang terbawa ombak ke tepian. Bau tidak sedap yang ditimbulkan menambah kesan jorok dan merusak pengalaman para pengunjung. Penyebab Utama Kerusakan Sampah Lautan Sebagian besar sampah yang terdampar di Pantai Batakan Baru berasal dari aktivitas masyarakat di sekitar sungai dan lautan. Limbah rumah tangga yang tidak dikelola dengan baik hanyut bersama aliran sungai dan bermuara di pantai ini. Kurangnya Kesadaran Pengunjung Beberapa pengunjung juga turut berkontribusi pada kerusakan lingkungan ini dengan meninggalkan sampah setelah berwisata. Plastik, botol minuman, dan kemasan makanan adalah jenis sampah yang sering ditemukan. Minimnya Fasilitas Kebersihan Ketidakhadiran tempat sampah yang memadai di sekitar pantai membuat pengelolaan limbah menjadi tantangan besar. Padahal, fasilitas seperti ini sangat penting untuk mendukung kebersihan kawasan wisata. Dampak Lingkungan dan Pariwisata Sampah yang menumpuk tidak hanya merusak pemandangan, tetapi juga membawa dampak buruk bagi ekosistem laut. Hewan laut sering kali terjebak atau bahkan memakan sampah plastik, yang berujung pada kematian mereka. Dari sisi pariwisata, kondisi ini membuat pantai kehilangan daya tariknya, berpotensi menurunkan jumlah kunjungan wisatawan dan pendapatan lokal. Harapan untuk Masa Depan Pantai Batakan Baru adalah simbol potensi wisata yang perlu dijaga. Upaya pembersihan massal, edukasi kepada masyarakat tentang pentingnya menjaga kebersihan, serta penyediaan fasilitas kebersihan yang memadai harus menjadi prioritas. Dengan kerjasama semua pihak, keindahan asli Pantai Batakan Baru dapat dipulihkan dan terbebas dari kesan jorok yang saat ini melekat. Sebagai pengunjung, mari bersama-sama menjadi bagian dari solusi. Bawalah sampahmu kembali dan bantu menjaga kebersihan lingkungan. Karena keindahan sejati dari Pantai Batakan Baru hanya dapat dinikmati jika ia bersih dan lestari.', 'pantai salah satu destinasi bahari yang letak kalimantan selatan simpan indah alam yang sejati mampu mikat hati para garis pantai yang panjang debur ombak yang tenang serta pohon pohon cemara jauh pantai jadi salah satu lokasi favorit bagi masyarakat balik potensi indah masalah besar tengah gerogot daya tarik pantai sampah gambar atas tunjuk kondisi prihatin pantai hampar pasir yang harus bersih manja mata kini tutup tumpu sampah plastik kayu kayu bekas limbah lain yang bawa ombak ke tepi bau tidak_sedap yang timbul tambah kesan kotor rusak alam para sebab utama rusa sampah laut bagi besar sampah yang dampar pantai asal dari aktivitas masyarakat sungai laut limbah rumah tangga yang tidak_kelola baik hanyut sama alir sungai muara pantai kurang sadar juga turut kontribusi pada rusa lingkung tinggal sampah plastik botol minum kemas makan jenis sampah yang sering temu minim fasilitas bersih ketidakhadiran sampah yang pada pantai buat kelola limbah jadi tantang besar fasilitas seperti sangat penting dukung bersih kawasan dampak lingkung pariwisata sampah yang tumpuk tidak_hanya rusak pandang juga bawa dampak buruk bagi ekosistem laut hewan laut sering kali jebak makan sampah plastik yang ujung pada mati dari sisi pariwisata kondisi buat pantai hilang daya tarik potensi turun kunjung wisatawan dapat lokal harap masa pantai simbol potensi yang perlu jaga upaya bersih massal edukasi masyarakat tentang penting jaga bersih serta sedia fasilitas bersih yang pada harus jadi prioritas kerjasama semua pihak indah asli pantai dapat pulih bebas dari kesan kotor yang lekat mari sama sama jadi bagi dari solusi bawa sampah kembali bantu jaga bersih lingkung karena indah sejati dari pantai hanya dapat nikmat bersih lestari', 'negatif', 'latih', '2026-04-27 22:52:46'),
(42, 'Banyak wisata: ATV, banana boat, berenang, naek klotok ke pulau seberang. Warung juga tersedia banyak. Sewa tikar juga tersedia. Banyak kursi pantai berdua di 1 tenda, tapi saya ngga tau apakah disewakan atau gratis. Banyak pohon jadi bisa berteduh. Ada beberapa gasebo juga bisa dipakai. Parkir masuk ke dalam, jadi keluar mobil langsung pantai. Jadi hati-hati klo bawa anak kecil karena kendaraan lewat-lewat. Ada toilet, tapi yang saya pakai langsung ke sungai, jadi ngga ada lantai & WC nya, hanya kayu berlubang. BAK 2rb, mandi 5rb. Bisa bawa tikar, jadi bisa piknik sambil bawa makan dari rumah. Sayang pantainya kotor banyak sampah. Kurang tersedia tempat sampah & tukang bersih-bersih. Juga kurang kesadaran pengunjung untuk menjaga kebersihan. Di pulau seberang, naik klotok sekitar 15 menit. Ada makam siapa gitu. Hutan kecil. Ada warung & toilet juga, tapi kotor. Air pantainya yang jernih & bersih krn mungkin jarang pengunjung. Berbatu-batu, indah viewnya. Pas saya kunjung ke sini ada yang camping, tapi klo bermalam harus izin dulu.', 'banyak atv banana renang naek perahu ke pulau seberang warung juga sedia banyak tikar juga sedia banyak kursi pantai dua saya tidak_tau gratis banyak pohon jadi bisa teduh ada gasebo juga bisa pakai parkir masuk ke dalam jadi keluar mobil langsung pantai jadi hati hati kalau bawa anak kecil karena kendara lewat lewat ada toilet yang saya pakai langsung ke sungai jadi tidak_ada wc hanya kayu lubang bak ribu mandi ribu bisa bawa tikar jadi bisa piknik bawa makan dari rumah sayang pantai kotor banyak sampah kurang_sedia sampah tukang bersih bersih juga kurang_sadar jaga bersih pulau seberang naik perahu menit ada makam siapa begitu hutan kecil ada warung toilet juga kotor air pantai yang jernih bersih karena mungkin jarang batu batu indah viewnya pas saya kunjung ke ada yang camping kalau malam harus izin', 'negatif', 'latih', '2026-04-27 22:52:46'),
(43, 'Bagus indah pantai nya tanjung dewa', 'bagus indah pantai tanjung dewa', 'positif', 'latih', '2026-04-27 22:52:46'),
(44, 'pantai batakan baru emng paling best buat menikmati sunset, rugi sih kalo yg blm pernah kesini', 'pantai memang baik buat nikmat sunset rugi kalau yang belum_pernah ke sini', 'positif', 'latih', '2026-04-27 22:52:46'),
(45, 'lumayan bersih, tidak terlalu ramai, suasananya tentram dan damai.. sangat cocok untuk berlibur', 'lumayan bersih tidak_terlalu ramai suasana tentram damai sangat cocok libur', 'positif', 'latih', '2026-04-27 22:52:46'),
(46, 'Secara keseluruhan pantai bagus, tapi terlalu banyak area yg di sewakan jadi serasa kurang nyaman untuk meng explore wilayah disekitar pantai ini. Sebagai masukan tolong disediakan tempat sampah yg memadai agar para pengunjung bisa membuang sampah ke tempat yg telah disediakan.', 'pantai bagus terlalu banyak yang jadi serasa kurang_nyaman meng explore wilayah pantai masuk tolong sedia sampah yang pada agar para bisa buang sampah ke yang sedia', 'negatif', 'latih', '2026-04-27 22:52:46'),
(47, 'Pantainya bagus. Sangat disayangkan kursi didekat pantai sekarang berbayar tidak geratis seperti terakhir aku krsana😁..', 'pantai bagus sangat sayang kursi dekat pantai bayar tidak_gratis seperti saya krsana', 'negatif', 'latih', '2026-04-27 22:52:46'),
(48, 'Sekarang banyak penginapan dan tenda tenda d sewakan jadi semakin semrawut gak kayak dl. Tp lmyan lah buat melepas penat ombak nya keren . Menenangkan', 'banyak inap d jadi makin semrawut tidak_seperti lmyan buat lepas penat ombak keren tenang', 'positif', 'latih', '2026-04-27 22:52:46'),
(49, 'Pantainya bagus, cukup bersih, tapi di beberapa tempat masih ada sampah menumpuk, banyak penjulan keliling, yang jual makanan minuman juga banyak jadi gampang buat cari makan, tersedia banyak penginapan, wc, kamar mandi, juga ada beberapa permainan seperti motor atv, banana boat, naik kuda , selncar,.', 'pantai bagus cukup bersih ada sampah tumpuk banyak penjulan keliling yang jual makan minum juga banyak jadi gampang buat cari makan sedia banyak inap wc kamar mandi juga ada main seperti motor atv banana naik kuda selncar', 'negatif', 'latih', '2026-04-27 22:52:46'),
(50, 'Maaf mengatakan ini, sebenarnya ini tempat wisata yg fasilitasnya sudah bagus tetapi sampahnya banyak sekali, dibibir pantai saja banyak sampah, tenda kami juga dihiasi sampah ketika disini, apalagi weekend. Mohon untuk pengelola agar pantainya selalu indah kebersihan dan sampah pengunjung di perhatikan. Jika ada yang membuang sampah tidak pada tempatnya dikenakan denda.', 'maaf kata benar yang fasilitas sudah bagus sampah banyak sekali bibir pantai saja banyak sampah juga hias sampah di sini weekend mohon kelola agar pantai indah bersih sampah perhati ada yang buang sampah tidak_pada kena denda', 'negatif', 'latih', '2026-04-27 22:52:46'),
(51, 'Lokasi : perjalanan lumayan jauh lebih enak d acces dengan bus untuk acara family. Tempat : kurang tertata semoga lebih baik lagi kedepannya karena ini wisata baru buka mungkin harus lebih fress lagi terutama kebersihan juga d jaga, cocok untuk liburan', 'lokasi jalan lumayan jauh lebih enak d acces bus acara family kurang_tata moga lebih baik lagi karena buka mungkin harus lebih fress lagi utama bersih juga d jaga cocok libur', 'negatif', 'latih', '2026-04-27 22:52:46'),
(52, 'Pantainya lumayan, namun sayang masih banyak sampah di area pantai dan sekitarnya. Semoga kedepannya pengunjung lebih bertanggung jawab lagi dengan sampah masing-masing dan untuk dinas terkait atau pengelola pantai untuk ditambah menyediakan tempat sampah di area sekitar pantai.', 'pantai lumayan sayang banyak sampah pantai moga lebih tanggung jawab lagi sampah dinas kait kelola pantai tambah sedia sampah pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(53, 'Pantainya bersih dan indah masih terjaga pemandangan alamnya kalo pagi da sore sangat adem buat santai di tepi pantai sambil menikmati pemandangan,. penduduknya ramah² dan sopan pengujungnya slalu ramai sehingga berasa betah Ig: Phieyo Motorvlog', 'pantai bersih indah jaga pandang alam kalau pagi da sore sangat adem buat santai tepi pantai nikmat pandang duduk ramah sopan ujung slalu ramai asa betah ig phieyo motorvlog', 'netral', 'latih', '2026-04-27 22:52:46'),
(54, 'Pantai luas dan aman untuk anak-anak, banyak warung-warung makan dan tempat berbilas, penginapan-penginapan kecil juga tersedia, banyak wahana permainan yg disewakan, sayangnya banyak sampah juga yang bertebaran karena kurangnya tempat sampah.', 'pantai luas aman anak anak banyak warung warung makan bilas inap inap kecil juga sedia banyak main yang sayang banyak sampah juga yang tebar karena kurang sampah', 'negatif', 'uji', '2026-04-27 22:52:46'),
(55, 'Pantainya bagus, tapi masih ada sampah yang berserakan. Tiket masuknya 5 rb per orang untuk penginapan seharga 250 rb. Dan banyak fasilitas seperti warung, musholla dan wahana bermain. Beberapa wahana bermain dimulai dari harga 50 rb. Pantai yang bagus', 'pantai bagus ada sampah yang sera tiket masuk ribu orang inap harga ribu banyak fasilitas seperti warung musholla main main mulai dari harga ribu pantai yang bagus', 'positif', 'latih', '2026-04-27 22:52:46'),
(56, 'Ini bisa jadi salah satu destinasi wisata pantai untuk keluarga, karena memiliki aneka fasilitas yang cukup lengkap, ada penginapan sederhana merangkap rumah makan bertebaran di sepanjang pantai, arena bermain seperti Playground, ATV, banana boat, kereta kuda, penyewaan ban atau pelampung, tenda kemah, tenda glamping, toko souvenir khas pantai, toko oleh2, lalu fasilitas bilas wc pun banyak disediakan dan semua fasilitas tersebut bisa di nikmati dengan harga cukup ramah di kantong... Hanya saja seperti layaknya pantai di wilayah kalimantan maka perairan di sini pun berwarna coklat dan memiliki ombak yang cukup deras jadi hati2 bila mandi ditempat ini.... menjelang senja ketika air laut mulai pasang maka air laut akan berubah sedikit kehijauan dan agak bersih.. jadi untuk kamu2 yang mengincar wisata pantai untuk mandi disarankan datang di sore hari. . Pemandangan Sunset sudah pasti bisa kita nikmati dengan luar biasa di tempat ini', 'bisa jadi salah satu destinasi pantai keluarga karena milik aneka fasilitas yang cukup lengkap ada inap sederhana rangkap rumah makan tebar panjang pantai arena main seperti playground atv banana kereta kuda ban pelampung kemah glamping toko souvenir khas pantai toko lalu fasilitas bilas wc pun banyak sedia semua fasilitas bisa nikmat harga cukup ramah kantong hanya saja seperti layak pantai wilayah kalimantan air pun warna keruh milik ombak yang cukup deras jadi hati mandi jelang senja air laut mulai pasang air laut ubah sedikit hijau agak bersih jadi yang incar pantai mandi saran datang sore pandang sunset sudah pasti bisa nikmat luar biasa', 'negatif', 'latih', '2026-04-27 22:52:46'),
(57, 'Pertama kalinya wisata ke Pantai Batakan Baru. Lumayan luas. Ada beberapa spot yang kotor banyak sampah, ada juga yang bersih. HTM 5.000/org. Banyak yang menyewakan tikar. Bisa berkeliling pantai menggunakan ATV, delman, atau berkuda. Terdapat banana boat juga. Banyak warung yang menyediakan makanan/minuman dan juga kamar mandi untuk bilas. Sunset-nya indah sekali di sini.', 'kali ke pantai lumayan luas ada spot yang kotor banyak sampah ada juga yang bersih htm orang banyak yang tikar bisa keliling pantai guna atv delman kuda dapat banana juga banyak warung yang sedia makan minum juga kamar mandi bilas sunset indah sekali', 'positif', 'latih', '2026-04-27 22:52:46'),
(58, 'Lebih nyaman ketika hari kerja jd gak perlu ngantri dan pastinya bisa dapat tempat yg nyaman di dalam. Utk kebersihan perlu ditingkatkan lagi, terutama pendopoanx itu kotor kmrn ada telek cecakx jd kita gak jd duduk² di situ. Utk penyewaan ATV agak mehong sih, rencana pengen naik kuda 🐎 tp gak ketemu.. selebihnya ya cukup lumayan utk piknik/camping di sana.', 'lebih nyaman kerja jadi tidak_perlu ngantri pasti bisa dapat yang nyaman dalam bersih perlu tingkat lagi utama pendopoanx itu kotor kmrn ada telek cecakx jadi tidak_jadi duduk situ atv agak mehong rencana ingin naik kuda tidak_ketemu lebih ya cukup lumayan piknik camping', 'positif', 'latih', '2026-04-27 22:52:46'),
(59, 'Ternyata di ujung pantai lebih bagus dah lebih Free untuk santai hampir pinggir pantai gak tertutup sama tenda Sewa warga setempat. Soal nya enak yg lesehan di sore hari. Smoga kedepan nya tempat kosong seperti ini gak di dirikan tempat tenda sewa biar enak bisa pasang tenda sendiri.', 'nyata ujung pantai lebih bagus sudah lebih free santai pinggir pantai tidak_tutup sama warga soal enak yang leseh sore smoga kosong seperti tidak_di diri biar enak bisa pasang sendiri', 'negatif', 'latih', '2026-04-27 22:52:46'),
(60, 'Atmosfernya oke, ada listriknya buat ngecas Hp. Klo ambles ada mobil khusus yg narik (seikhlasnya aja) Nongkrong mobil pinggir pantai kena charge 5k, masih masuk lah. Soapnya dapet listrik 😂. PR utamanya: kebersihan pantai bisa ditingkatkan lagi. Padahal tempat sampah udah cukup memadai. Tapi kalau ngarep pengunjung sadar kebersihan, sepertinya syuliit. Kudu pengelola yang “berbesar hati” buat bersih bersih. Semangat yaa', 'atmosfer oke ada listrik buat ngecas hp kalau ambles ada mobil khusus yang narik ikhlas saja nongkrong mobil pinggir pantai kena charge k masuk soapnya dapet listrik pr utama bersih pantai bisa tingkat lagi sampah sudah cukup pada kalau ngarep sadar bersih seperti syuliit kudu kelola yang besar hati buat bersih bersih semangat ya', 'negatif', 'latih', '2026-04-27 22:52:46'),
(61, 'Seru, karena datang pertama kali rombongan sama keluarga di bulan januari. Kedua datang rombongan sekolah. Cukup bagus tempatnya, ada banana boat, motor motoran (lupa namanya), boat nya ada yang bulat juga, bisa ke pulau seberang, ada tenda dekat pantai bisa sewa tapi lumayan banyak sampah dipinggir pantai dan kalo malam tidak ada penerangan di pinggir pantai. Sewa kamar mandi untuk buang air kecil/besar dan mandi mulai dari 3k-10k. Makan juga standar lah, nasi 10kan gak mahal. Sewa penginapan 250kan yang biasa. Penginapan anisa yang warna kuning bagus, bersih, dan nyaman. Jajanan di pinggir pantai juga banyak, enak, dan murah (gak kaya di pantai lain yang biasa mahal mahal). Banyak jual ikan kering, kerupuk, amplang, acan, dll hasil laut di warung warung dekat penginapan. Harus pergi bareng keluarga atau ramean biar seru sih 😎', 'asik karena datang kali rombong sama keluarga bulan januari dua datang rombong sekolah cukup bagus ada banana motor motor lupa nama ada yang bulat juga bisa ke pulau seberang ada dekat pantai bisa lumayan banyak sampah pinggir pantai kalau malam tidak_ada pinggir pantai kamar mandi buang air kecil besar mandi mulai dari k k makan juga standar nasi kan tidak_mahal inap kan yang biasa inap anisa yang warna kuning bagus bersih nyaman jajan pinggir pantai juga banyak enak murah tidak_kaya pantai lain yang biasa mahal mahal banyak jual ikan kering kerupuk amplang acan dan lain hasil laut warung warung dekat inap harus pergi bareng keluarga ramean biar asik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(62, 'Dulu kebatakan 2021. Dan baru sekarang ke batakan lagi. Jauh berbeda sii, kalo dlu bersihh, lebih berasa damai, karena belum banyak yg jualan dll. Sekarang dan aku datang waktu liburan idul adha jadi bwanyak sekali orangg, dan orang yg jualan, serta glamping2nya🍃. Kalo saat masuk beloknya ke kiri, dikiri kebanyak glamping⛺️. Tapi jujur lebih sepi, jdi tidak terlalu banyak orang, dan tidak banyak yg jualan. Jadi lebih nyaman menikmati pantainya 🌊', 'ke lagi jauh beda sii kalau dlu bersih lebih asa damai karena belum_banyak yang jual dan lain saya datang waktu libur idul adha jadi banyak sekali orangg orang yang jual serta glamping kalau masuk belok ke kiri kiri banyak glamping jujur lebih sepi jdi tidak_terlalu banyak orang tidak_banyak yang jual jadi lebih nyaman nikmat pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(63, 'Entah knpa org yg memanfaatkan pantai disana tdk merawat n menjaga kebersihan pantai terutama yg jualan.. Pantaixsangat kotor banyak sampah n ranting kayu berserakan...', 'entah knpa orang yang manfaat pantai di sana tidak_rawat n jaga bersih pantai utama yang jual pantaixsangat kotor banyak sampah n ranting kayu sera', 'negatif', 'latih', '2026-04-27 22:52:46'),
(64, 'Dari Kuala Kurun Gunung Mas kesini bareng keluarga, pantainya lumayan, cuma untuk penjaga pantainya gak ada jadi khawatir sama yg bawa anak takut terbawa arus. Petugas pantai maupun penduduk lokal disekitar sangat ramah🥳 harga barang juga murah²', 'dari kuala kurun gunung mas ke sini bareng keluarga pantai lumayan hanya jaga pantai tidak_ada khawatir sama yang bawa anak takut bawa arus tugas pantai duduk lokal sangat ramah harga barang juga murah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(65, 'Liburan keluarga, pantai tidak bersih.. mungkin org yg kesini suka buang sampah sembarang, no no ya gaiiss tidak untuk ditiruuu🙏🏻', 'libur keluarga pantai tidak_bersih mungkin orang yang ke sini suka buang sampah sembarang tidak_tidak ya gaiiss tidak_untuk ditiruuu', 'negatif', 'latih', '2026-04-27 22:52:46'),
(66, 'Andong atau dokar kuda banyak ber sliweran sayangnya tidak diberi penampungan kotoran kuda. Sehingga kotorannya bertebaran di pinggir pantai dan menyebarkan bau yg menyengat.', 'andong dokar kuda banyak ber sliweran sayang tidak_beri tampung kotor kuda kotor tebar pinggir pantai sebar bau yang sengat', 'negatif', 'latih', '2026-04-27 22:52:46'),
(67, 'Seru juga pantainya, walaupun ngga terlalu bersih. Banyak penyewaan tenda, ada banana boat, ATV, warung banyak. Tp angin akhir tahun kencang bgt.', 'asik juga pantai tidak_terlalu bersih banyak ada banana atv warung banyak angin kencang banget', 'positif', 'latih', '2026-04-27 22:52:46'),
(68, 'Tempatnya bagus. Banyak permainan yg disajikan. Tepi agar bisa ditingkatkan lagi untuk pengelolaan sampah nya. Karena menganggu pemandangan dan bisa merusak keindahan dan ekosistem alam sekitar nya. Saran jika bisa ditambahkan tong2 sampah atau kotak smapah disekitar2 tenda camping agar tidak berhamburan dilokasi dan disekitar pantai. Semoga lebih baik lagi kedepannya.', 'bagus banyak main yang saji tepi agar bisa tingkat lagi kelola sampah karena menganggu pandang bisa rusak indah ekosistem alam saran bisa tambah tong sampah kotak smapah camping agar tidak_hambur lokasi pantai moga lebih baik lagi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(69, 'Merasakan udara malam di pinggir pantai, tempat yg bersahabat dengan keluarga kalau ingin camping bersama keluarha', 'rasa udara malam pinggir pantai yang sahabat keluarga kalau ingin camping sama keluarha', 'negatif', 'latih', '2026-04-27 22:52:46'),
(70, 'Sudah 4 kali kesini, waktu awal pertama kesini masih nyaman perihal kebersihan dan tarif parkir nya, dan terakhir kemaren kesini sama istri bermalam, kita datang nya malam, tarif parkir boleh mahal tp tolong dijaga kebersihannya, percuma rame tp mau camping aja susah cari tempat bersih, apalagi sekarang terlalu banyak tenda sewa, tidak banyak lahan kosong buat yang dirikan tenda sendiri, dan kita pun juga terganggu, oleh orang yang muter muter pakai motor knalpot blong yang berisik dari tengah malam sampai subuh, tolong diperbaiki 🥱', 'sudah kali ke sini waktu awal ke sini nyaman perihal bersih tarif parkir kemaren ke sini sama istri malam datang malam tarif parkir boleh mahal tolong jaga bersih percuma rame mau camping saja susah cari bersih terlalu banyak tidak_banyak lahan kosong buat yang diri sendiri pun juga ganggu orang yang muter muter pakai motor knalpot blong yang berisik dari tengah malam sampai subuh tolong baik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(71, 'Salah satu pantai yang paling ramai dan menarik yang saya kunjungi di kalsel. Terdapat banyak hiburan seperti playground, dan ATV. Fasilitas juga lengkap dari wc, km, rumah makan, tempat menginap. Pantai yang cocok buat berkemah juga karena pantainya sangat luas', 'salah satu pantai yang ramai tarik yang saya kunjung kalsel dapat banyak hibur seperti playground atv fasilitas juga lengkap dari wc km rumah makan inap pantai yang cocok buat kemah juga karena pantai sangat luas', 'negatif', 'latih', '2026-04-27 22:52:46'),
(72, 'Pantainya bagus cuma saat lagi surut dan banyak kayapu. Banyak fasilitas seperti WC, kamar mandi, mushola, gazebo, dll.', 'pantai bagus hanya lagi surut banyak kayapu banyak fasilitas seperti wc kamar mandi mushola gazebo dan lain', 'negatif', 'uji', '2026-04-27 22:52:46'),
(73, 'Padahal nyari kuda/delman ternyata gak ada. 😹 Penginapan banyak rata 250rb per malam.. kalo bisa nawar bisa dapat 200rb hihihi Naik ATV 50rb per 20 menit. Biaya masuk kmaren dewasa 2 balita 2 pake mobil bayar 14rb di hari jumat.', 'cari kuda delman nyata tidak_ada banyak rata ribu malam kalau bisa nawar bisa dapat ribu hihihi naik atv ribu menit biaya masuk kmaren dewasa balita pake mobil bayar ribu jumat', 'negatif', 'latih', '2026-04-27 22:52:46'),
(74, 'Alhamdulillaah,akhirnya bisa kesampaian juga bisa main ke pantai. Bisa camping di tepi pantai. Lumayan bisa bawa tenda sendiri, dan gabung di lokasi tenda dg biaya yg sangat murah dan free KM. Mantap pokoknya..Namun sayangnya masih banyak pengunjung yg kurang sadar dg kebersihan, masih banyak yg buang sampah sembarangan.. \"Jangan hanya mau menikmati, namun kepedulian utk menjaga nikmat Allah minus\"..Semoga banyak orang yg disadarkan utk peduli ke lingkungan ...', 'alhamdulillaah bisa sampai juga bisa main ke pantai bisa camping tepi pantai lumayan bisa bawa sendiri gabung lokasi biaya yang sangat murah free km mantap pokok sayang banyak yang kurang_sadar bersih banyak yang buang sampah sembarang jangan_hanya mau nikmat peduli jaga nikmat allah minus moga banyak orang yang sadar peduli ke lingkung', 'negatif', 'uji', '2026-04-27 22:52:46'),
(75, 'jalan menuju pantainya mulus,biaya masuk 5000/orang, sunset di pantai batakan baru sangat indah sekali, tersedia fasilitas mushola, toilet, kamar bilas, penginapan, dan berbagai penyewaan seperti tenda/atv/ban, ada kuda dan wahana bananaboad, pantai batakan selalu jadi tujuan utama kami kalau kepantai, karna jarak tempuh yang lumayan dekat dari banjarmasin hanya 2-3jam perjalanan, rekomen untuk wisata keluarga', 'jalan tuju pantai mulus biaya masuk orang sunset pantai sangat indah sekali sedia fasilitas mushola toilet kamar bilas inap seperti atv ban ada kuda bananaboad pantai jadi tuju utama kalau pantai karena jarak tempuh yang lumayan dekat dari banjarmasin hanya jam jalan rekomen keluarga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(76, 'Bagus untuk berlibur leluarga dgn suasana pantai ada tenda besar dan kecil, ada kuda, adabanan boot ada motor app nya. Yah lumayab', 'bagus libur leluarga suasana pantai ada besar kecil ada kuda adabanan boot ada motor app yah lumayab', 'positif', 'latih', '2026-04-27 22:52:46');
INSERT INTO `ulasan` (`id`, `teks_asli`, `teks_clean`, `label`, `tipe_data`, `tanggal_input`) VALUES
(77, 'Pantainya bersih, anak puas main disana. Bisa sewa tenda disana. Orang yang nyewain tenda juga ramah, bantuin bikin xtra tenda karena kemarin hujan, dapat free kamar mandi sepuasnya dan tempat sholat. Bisa beli sabun / shampoo sachetnya juga, harganya murah.', 'pantai bersih anak puas main di sana bisa di sana orang yang nyewain juga ramah bantuin bikin xtra karena kemarin hujan dapat free kamar mandi puas sholat bisa beli sabun shampoo sachetnya juga harga murah', 'positif', 'latih', '2026-04-27 22:52:46'),
(78, 'View nya bagus dan memanjakan mata, cocok untuk refreshing dari hiruk-piruk pekerjaan,fasilitas nya bagus dan bersih ,semoga dengan naik nya harga tiket masuk bisa meningkatkan pelayanan dan kelayakan fasilitas nya', 'view bagus manja mata cocok refreshing dari hiruk piruk kerja fasilitas bagus bersih moga naik harga tiket masuk bisa tingkat layan layak fasilitas', 'positif', 'latih', '2026-04-27 22:52:46'),
(79, 'Salah satu tempat wisata pantai yg wajib dikunjungi di Kalsel. Pantainya luas,penginapan tersedia banyak, cm klo mlm agak berisik soalx penginapan pinggir jln. Banyak yg jualan jg untuk oleh2, wahana yg tersedia jg menarik....', 'salah satu pantai yang wajib kunjung kalsel pantai luas inap sedia banyak hanya kalau mlm agak berisik soalx inap pinggir jln banyak yang jual juga yang sedia juga tarik', 'negatif', 'uji', '2026-04-27 22:52:46'),
(80, 'Pantai nya bagus kalo kita naik banana boat kya kolak pisang. Pengalaman terakhir ke batakan sabtu kemaren tanggal 9 maret 2024 dan bertepatan anak santri ilang. Malah tenda kami sebelahan lagi', 'pantai bagus kalau naik banana kya kolak pisang alam ke sabtu kemaren tanggal maret tepat anak santri ilang belah lagi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(81, 'Rekomendasi utk liburan hemat dan dekat dr Kota Banjarbaru yaa ke pantai Batakan', 'rekomendasi libur hemat dekat dari kota banjarbaru ya ke pantai', 'positif', 'latih', '2026-04-27 22:52:46'),
(82, 'Pantai Batakan Baru adalah salah satu pantai yang paling terkenal di Kalimantan Selatan, cocok banget buat dijadikan tempat liburan bersama keluarga, teman dan pasangan kalian. Menurutku pantai ini cocok banget buat kalian para pencinta sunset. Kalo kalian mau menginap di sana gak perlu bingung nyari tempat, karena di sana tersedia banyak penginapan yang aman dan nyaman. Selamat berlibur ✨ Bagus tmpatnya. Penginapan nya jg banyak yg di pinggir pantai, jdi bisa sambil menikmati indah nya pantai. Cuma sebagai wisatawan jangan buang sampah sembarangan ya. Tempat sampah juga udah disediakan. Jd tetap jaga kebersihannya ya, biar tetap enak dipandang.', 'pantai salah satu pantai yang kenal kalimantan selatan cocok banget buat jadi libur sama keluarga teman pasang turut pantai cocok banget buat para cinta sunset kalau mau inap tidak_perlu bingung cari karena sedia banyak inap yang aman nyaman selamat libur bagus tmpatnya inap juga banyak yang pinggir pantai jdi bisa nikmat indah pantai hanya wisatawan jangan_buang sampah sembarang ya sampah juga sudah sedia jadi tetap jaga bersih ya biar tetap enak pandang', 'positif', 'latih', '2026-04-27 22:52:46'),
(83, 'Fasilitas nya lengkap makanannya juga murah tapi pantai nya banyak sekali sampah', 'fasilitas lengkap makan juga murah pantai banyak sekali sampah', 'negatif', 'uji', '2026-04-27 22:52:46'),
(84, 'Untuk orang introvert cocok ni, apalagi di hari kerja. Soalnya agak sepi, serasa pantai pribadi aja. Disini gak ada yg jual oleh\" aksesoris/pernak pernik gitu. Nilai ++nya disini banyak wc/kamar mandi dan bersih\" tentunya ya karna masing\" ada pengelolanya yaitu pemiliknya. Acil paman warungnya ramah\", kemaren kewarung yg ada monyetnya, puput kalo gak salah namanya, monyetnya lucu, suka dielus dan gak bar\" 🤣', 'orang introvert cocok ni kerja soal agak sepi serasa pantai pribadi saja di sini tidak_ada jual aksesoris pernak pernik begitu nilai di sini banyak wc kamar mandi bersih tentu ya karena ada kelola milik acil paman warung ramah kemaren warung yang ada monyet puput kalau tidak_salah nama monyet lucu suka elus tidak_bar', 'positif', 'latih', '2026-04-27 22:52:46'),
(85, 'Ku ingat sebagai kenangan bersama orang tua satu2 nya ..mama sehat2 yaa ..', 'ku ingat kenang sama orang tua satu mama sehat ya', 'positif', 'latih', '2026-04-27 22:52:46'),
(86, 'Menikmati matahari terbenam di jembatan pantai, banyak aktivitas yang bisa dilakukan di pantai ini dari wahana air sampai darat Bersantai di gazebo, menunggang kuda, mencari kulit kerang, bermain motoran ATV, bermain air, banana bot dan banyak hal lainnya yg bisa dilakukan', 'nikmat matahari benam jembatan pantai banyak aktivitas yang bisa laku pantai dari air sampai darat santa gazebo tunggang kuda cari kulit kerang main motor atv main air banana bot banyak lain yang bisa laku', 'negatif', 'latih', '2026-04-27 22:52:46'),
(87, 'Kesini waktu weekday jadi gabanyak org dan penujual banyak tutup , disana kami makan bakso dan pop es cuaca ny saat itu panas banget jadi rasa nya males bngt berjemur siang panas. Jadi kami putuskan maakn2 aja di gazebo. Jadi ps waktu agak naung kami main air d pantai. Tapi kurang angin karna hawa ny dr awal panas. Seharian g ad hujan. Sayang bgt gaada banana boat dpikir disinia ad. Tapi dsini ada atv juga . Untuk air bersih trsedia aj disini sperti bisa bayar BAB = 3k BAK = 2K mandi = 5K. Saya paling suka suasan menuju ke pantai nya. Banyak menemui pohon2 gunung2 jdi bisa lumayan melepas penat sejenak .', 'ke sini waktu weekday jadi gabanyak orang penujual banyak tutup di sana makan bakso pop es cuaca ny itu panas banget jadi rasa males banget jemur siang panas jadi putus maakn saja gazebo jadi ps waktu agak naung main air d pantai kurang_angin karena hawa ny dari awal panas g ada hujan sayang banget gaada banana dpikir sia ada dsini ada atv juga air bersih trsedia aj di sini sperti bisa bayar bab k bak k mandi k saya suka suasan tuju ke pantai banyak temu pohon gunung jdi bisa lumayan lepas penat jenak', 'negatif', 'latih', '2026-04-27 22:52:46'),
(88, 'Seru sih,,, cumen bagi pengelola harap di beri arahan atau beri informasi bagi para pengunjung kalo ngecamp ad yg mesti harus di bayar lgi... jgn pas sdh banyak tenda2 terpasang lalu diminta bayaran untuk lapak tenda...', 'asik cumen bagi kelola harap beri arah beri informasi bagi para kalau ngecamp ada yang mesti harus bayar lgi jangan_pas sudah banyak pasang lalu minta bayar lapak', 'negatif', 'latih', '2026-04-27 22:52:46'),
(89, 'jujur, bagusnya pas sore aja, dan jajanan semuanya harga turis', 'jujur bagus pas sore saja jajan semua harga turis', 'positif', 'latih', '2026-04-27 22:52:46'),
(90, 'Malam malam ada pungli 20k per tenda katanya penerangan dan sampah tapi masih berserakan dan gelap', 'malam malam ada pungli k kata terang sampah sera gelap', 'negatif', 'uji', '2026-04-27 22:52:46'),
(91, 'Mantap 👍 Disini terdapat ATV dan Banana Boat, selain itu disarankan untuk booking penginapan terlebih dahulu jika ingin menginap di pantai ini karena biasanya tempat penginapan selalu penuh apalagi disaat hati libur, tapi jangan khawatir disini juga disediakan tenda untuk menginap.', 'mantap di sini dapat atv banana itu saran booking inap lebih dahulu ingin inap pantai karena biasa inap penuh hati libur jangan_khawatir di sini juga sedia inap', 'positif', 'uji', '2026-04-27 22:52:46'),
(92, 'Sayang sekali pantainya masih banyak sampah. Semoga kedepannya lebih diperhatikan lagi. Kemarin tgl 31 mei diberkahi bgt dpt view sunset+++++', 'sayang sekali pantai banyak sampah moga lebih perhati lagi kemarin tgl mei kah banget dapat view sunset', 'negatif', 'latih', '2026-04-27 22:52:46'),
(93, 'Pros : Lumayan bersih, bagus untuk spot foto, tersedia macam-macam sarana rekreasi Cons : Akses sanitasi kurang memadai, sangat ramai saat weekend, jalan masuk untuk transportasi roda dua agak sulit', 'pros lumayan bersih bagus spot foto sedia macam macam sarana rekreasi cons akses sanitasi kurang_pada sangat ramai weekend jalan masuk transportasi roda dua agak sulit', 'negatif', 'latih', '2026-04-27 22:52:46'),
(94, 'Pantai nya sangat bagus dan sangat cocok untuk liburan sekeluarga', 'pantai sangat bagus sangat cocok libur keluarga', 'positif', 'latih', '2026-04-27 22:52:46'),
(95, 'mantab.. bagus, indah, bersih.. jauh berbeda dgn yg dulu.. banyak penginapan, tenda, glamping, serta wahana laut yg ditawarkan.', 'mantab bagus indah bersih jauh beda yang banyak inap glamping serta laut yang tawar', 'netral', 'uji', '2026-04-27 22:52:46'),
(96, 'Dear Bapak Ibu DINAS Pemerintahan Terkait. Pantai ini Salah satu potensi wisata provnsi kalsel. Dermaga nya sudah pada Rusak, alangkah baik nya Di ganti. Sungguh Bahaya untuk anak2 dan pengunjung yg hendak berfoto. MCK juga kebersihan kurang twrawat. Sampah Di pinggir pantai memerlukan perhatian.Terimakasih atas perhatian nya, semoga segera Di tindak lanjuti.', 'dear dinas perintah kait pantai salah satu potensi provnsi kalsel dermaga sudah pada rusak alangkah baik ganti sungguh bahaya anak yang hendak foto mck juga bersih kurang_twrawat sampah pinggir pantai perlu perhati terimakasih atas perhati moga segera tindak lanjut', 'negatif', 'latih', '2026-04-27 22:52:46'),
(97, 'sekarang lebih banyak penginapannya jadi lebih nyaman buat yang dateng dari jauh, harganya lumayan tapi menurutku worth it sih yaa. pantainya seperti pantai pada umumnya sih bagus lah👍🏻👍🏻', 'lebih banyak inap jadi lebih nyaman buat yang dateng dari jauh harga lumayan turut padan it ya pantai seperti pantai pada umum bagus', 'positif', 'latih', '2026-04-27 22:52:46'),
(98, 'Siang frend, testimoni saja. baru pertama kali ke pantai batakan baru, sengaja janjian dengan temen2 di kantor, trus sewa tenda deh. sampai lokasi jadi amazing karena udah banyak yang pasang tenda. daratan pantainya panjang dan lebar. ada permainan motor atv dan banana boat. buat yang malas pasang tenda, ada banyak penginapan. recomended deh pokok e :-)', 'siang frend testimoni saja kali ke pantai sengaja janji temen kantor terus saja sampai lokasi jadi amazing karena sudah banyak yang pasang darat pantai panjang lebar ada main motor atv banana buat yang malas pasang ada banyak inap recomended saja pokok e', 'negatif', 'latih', '2026-04-27 22:52:46'),
(99, 'Kurang serius mengelola pantai. Banyak sampah, botol kaca, batang pohon kayu mati gak di buang. Tolong dinas pariwisata kasih alat berat untuk perawatan pantai', 'kurang_serius kelola pantai banyak sampah botol kaca batang pohon kayu mati tidak_di buang tolong dinas pariwisata kasih alat berat awat pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(100, 'Pantai ny bersih harga makanan dan minuman juga terjangkau.penyewaan kursi 50k dan tikar 20k .semuanya ramah tamah .bisa pindh tempat kalau kepanasan.tapi gak bayar lagi makasih ya amang pengelola🙏 …', 'pantai ny bersih harga makan minum juga jangkau kursi k tikar k semua ramah tamah bisa pindh kalau panas tidak_bayar lagi makasih ya amang kelola', 'positif', 'latih', '2026-04-27 22:52:46'),
(101, 'Pantai nya cantik, semakin kesini juga semakin berbenah, jam 5 an aja sunset nya udah mulai keliatan, langit nya cantik Tapi mohon maaf, para pengunjung tolong sampah nya ya, jangan ditinggal 🙏', 'pantai cantik makin ke sini juga makin benah jam an saja sunset sudah mulai liat langit cantik mohon maaf para tolong sampah ya jangan_tinggal', 'positif', 'latih', '2026-04-27 22:52:46'),
(102, 'Karcis masuk 5rb per org Parkir 5 rb per mobil Sewa tenda besar 200 s.d 300rb sepuasnya Sewa kursi pantai dengan payung besar 50eb sepuasnya Banana boat 20 rb per org Pelampung 20 rb Atv 50rb, 20 menit Ada kamar mandi dan air bersih utk mandi', 'karcis masuk ribu orang parkir ribu mobil besar s d ribu puas kursi pantai payung besar eb puas banana ribu orang pelampung ribu atv ribu menit ada kamar mandi air bersih mandi', 'positif', 'latih', '2026-04-27 22:52:46'),
(103, 'bagus tpi sayang bgt airnya coklat', 'bagus sayang banget air keruh', 'negatif', 'latih', '2026-04-27 22:52:46'),
(104, 'Pantai nya cocok sekali untuk liburan keluarga dan penduduk nya juga ramah Mandi:5k Kencing: 2k Tikar : 20k Masuk kendaraan bermotor: 10k Naik ATV:50k/20 menit Banana boat: 100k untuk 5-6 orang', 'pantai cocok sekali libur keluarga duduk juga ramah mandi k kencing k tikar k masuk kendara motor k naik atv k menit banana k orang', 'positif', 'latih', '2026-04-27 22:52:46'),
(105, 'Kalau kesini, bisa nyewa gajebo 100 RB/permalam, jadi tidur langsung dekat pantai. Saran aja, kalau nyewa gajebo bawa selimut + autan + bantal + tilam tipis sendiri. Dari pihak penyewaan gajebo cuma nyediain tikar tipis buat alas gajebo nya. Untuk 1 gajebo muat 4-5 orang.', 'kalau ke sini bisa gajebo ribu malam jadi tidur langsung dekat pantai saran saja kalau gajebo bawa selimut autan bantal tilam tipis sendiri dari pihak gajebo hanya nyediain tikar tipis buat alas gajebo gajebo muat orang', 'negatif', 'latih', '2026-04-27 22:52:46'),
(106, 'Waktu datang pertama, masih awal² pantai ini buka, pantainya bersih dan cantik. Sekarang sudah banyak sampah bertebaran, diperlukan tempat sampah yang banyak dan kesadaran dari pengunjung pantai itu sendiri untuk menjaga lingkungan', 'waktu datang awal pantai buka pantai bersih cantik sudah banyak sampah tebar perlu sampah yang banyak sadar dari pantai itu sendiri jaga lingkung', 'negatif', 'latih', '2026-04-27 22:52:46'),
(107, 'Pantai Batakan Baru adalah salah satu pantai yang paling terkenal di Kalimantan Selatan, cocok banget buat dijadikan tempat liburan bersama keluarga, teman dan pasangan kalian. Menurutku pantai ini cocok banget buat kalian para pencinta sunset. Kalo kalian mau menginap di sana gak perlu bingung nyari tempat, karena di sana tersedia banyak penginapan yang aman dan nyaman. Selamat berlibur ✨', 'pantai salah satu pantai yang kenal kalimantan selatan cocok banget buat jadi libur sama keluarga teman pasang turut pantai cocok banget buat para cinta sunset kalau mau inap tidak_perlu bingung cari karena sedia banyak inap yang aman nyaman selamat libur', 'positif', 'latih', '2026-04-27 22:52:46'),
(108, 'Banyak tersedia sewa tenda untuk menginap, penginapan bangunan juga banyak, untuk nginap di tenda fasilitas ada colokan listrik, lampu dll tergantung pesan kebutuhan apa', 'banyak sedia inap inap bangun juga banyak nginap fasilitas ada colok listrik lampu dan lain gantung pesan butuh apa', 'negatif', 'latih', '2026-04-27 22:52:46'),
(109, 'Pantainya bagus untuk liat sunset posisinya pas Masih bersih Pantainya masih luas sehingga masih bisa bermain di pasir pantainya Ada banyak wahana dari berkuda, atv, banana boat, speed boat, perahu wahana, dll Tiketnya masih murah dan free parkir Ada banyak penginapan jd jika ingin bermalam bisa Bisa juga untuk ngecamp di pantai Ada jugatmpt beli oleh oleh', 'pantai bagus liat sunset posisi pas bersih pantai luas bisa main pasir pantai ada banyak dari kuda atv banana speed perahu dan lain tiket murah free parkir ada banyak inap jadi ingin malam bisa bisa juga ngecamp pantai ada jugatmpt beli', 'positif', 'latih', '2026-04-27 22:52:46'),
(110, 'Kemarin kesini ginep diGlamping, tempat penyewaan tenda dan lokasinya private, yang langsung menghadap ke pantainya, lumayan jauh dari titik keramaian, tapi bukan berarti sepi, tapi aku suka yg kaya gini 🤭🤭 …', 'kemarin ke sini ginep diglamping lokasi private yang langsung hadap ke pantai lumayan jauh dari titik ramai bukan_arti sepi saya suka yang kaya gin', 'negatif', 'latih', '2026-04-27 22:52:46'),
(111, 'Hiburan, bawain anak² main disana ada banyak permainan,makanan dekat masjid dan awas lumpur lautnya sangat gatal, harus mandi dibilas sabun dgn ber ulang²,, bahka sudah 1 bulan efek gatal.masih bersa', 'hibur bawain anak main di sana ada banyak main makan dekat masjid awas lumpur laut sangat gatal harus mandi bilas sabun ber ulang bahka sudah bulan efek gatal bersa', 'negatif', 'latih', '2026-04-27 22:52:46'),
(112, 'Dari dulu sampai sekarang suka banget sama pantai nya, cuman sekarang biayanya tambah mahal, dari masuk 22.000 abis itu klo camping malam nya dipintai lagi 20.000 kata nya buat kebersihan, kamaren\" ga ada dipintai kek gitu.', 'dari sampai suka banget sama pantai hanya biaya tambah mahal dari masuk abis itu kalau camping malam pinta lagi kata buat bersih kamaren tidak_ada kek begitu', 'negatif', 'latih', '2026-04-27 22:52:46'),
(113, 'Kotor sekali,, dari ujung sampai ke ujung,,. Pengelola hanya mengambil uang saja tidak dengan pembersihan sampah walaupun itu bawaan sampah laut setidak nx ad upaya pembersihan dari pengelola pantai,,. Yang awal nx mau mandi jadi tidak mood karna kotor,, serasa mandi dengan sampah, ,.', 'kotor sekali dari ujung sampai ke ujung kelola hanya ambil uang saja tidak_dengan bersih sampah itu bawa sampah laut tidak nx ada upaya bersih dari kelola pantai yang awal nx mau mandi jadi tidak_mood karena kotor serasa mandi sampah', 'negatif', 'uji', '2026-04-27 22:52:46'),
(114, 'Disarankan untuk reservasi tempat jauh² hari jika ingin menginap disini. Dan untuk jalan menuju ke pantai ini masih bisa terbilang bagus, walaupun jalan ketika ingin mendekati pantai masih ada beberapa jalan yang berlubang.', 'saran reservasi jauh ingin inap di sini jalan tuju ke pantai bisa bilang bagus jalan ingin dekat pantai ada jalan yang lubang', 'positif', 'latih', '2026-04-27 22:52:46'),
(115, 'Pantainya bagus, perlu peningkatan untuk kebersihan lokasi dan fasilitas keselamatan bagi para pengunjung yang berenang di pantai', 'pantai bagus perlu tingkat bersih lokasi fasilitas selamat bagi para yang renang pantai', 'positif', 'uji', '2026-04-27 22:52:46'),
(116, 'Menurut saya tempatnya lumayan enak, dekat dengan yg berjualan jadi gampang bila kelaparan hehe, juga banyak akses untuk mainan, seperti banana boat, motor, delman, atau ke pulau datu dengan kapal pemandangannya juga bagus', 'turut saya lumayan enak dekat yang jual jadi gampang lapar tertawa juga banyak akses main seperti banana motor delman ke pulau datu kapal pandang juga bagus', 'negatif', 'latih', '2026-04-27 22:52:46'),
(117, 'Lumayan aesthetic, tapi sampah dari pantai masih bergeletakan, dan banyak pecahan botol kaca jadi hati2 ya guys. recomended buat hammockan si atau santai dengan keluarga. dan jika anda beruntung anda akan mendapatkan sunsed terbaik.', 'lumayan aesthetic sampah dari pantai geta banyak pecah botol kaca jadi hati ya guys recomended buat hammockan si santai keluarga anda untung anda dapat sunsed baik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(118, 'Banyak fasilitas seperti ATV, Banana boat, WC, kamar mandi, musholla, dan kursi santai dipinggir pantai dan penginapan seperti tenda tapi ada tempat tidurnya dan banyak warung berjualan hasil laut', 'banyak fasilitas seperti atv banana wc kamar mandi musholla kursi santai pinggir pantai inap seperti ada tidur banyak warung jual hasil laut', 'negatif', 'latih', '2026-04-27 22:52:46'),
(119, 'Seru untuk berlibur akhir pekan... Wahana cukup memadai untuk wisata pantai... Dan cukup bersih... Next time back again...', 'asik libur pekan cukup pada pantai cukup bersih next time back again', 'negatif', 'latih', '2026-04-27 22:52:46'),
(120, 'Wisata merakyat yang ada di kalsel, tiket masuknya murah hanya 5k sudah plus parkir. Mantap jiwa Dinas Pariwisata Kab. Tanah Laut ⭐️⭐️⭐️⭐️⭐️', 'rakyat yang ada kalsel tiket masuk murah hanya k sudah plus parkir mantap jiwa dinas pariwisata kab tanah laut', 'negatif', 'latih', '2026-04-27 22:52:46'),
(121, 'Cocok untuk bawa keluarga ke pantai ini. Penginapannya banyak, makan disini juga ga mahal. Mau main motoran ada, main banana boat juga ada di pantai ini.', 'cocok bawa keluarga ke pantai inap banyak makan di sini juga tidak_mahal mau main motor ada main banana juga ada pantai', 'positif', 'latih', '2026-04-27 22:52:46'),
(122, 'Pantainya bagus tpi terlalu bising sound horeg padahal malam hari waktu istirahat.... Tolong dong berlakukan jam untuk org yang menyalakan sound system jangan sampai shubuh, kami pengunjung lain juga butuh ketenangan saat istirahat...sdh jauh² kesini tpi disuguhkan sound horeg yg bikin telinga budek saat tengah malam', 'pantai bagus terlalu berisik sound horeg malam waktu istirahat tolong laku jam orang yang nyala sound system jangan_sampai shubuh lain juga butuh tenang istirahat sudah jauh ke sini suguh sound horeg yang bikin telinga budek tengah malam', 'negatif', 'latih', '2026-04-27 22:52:46'),
(123, 'Tepat dibelang Sunrise resort dan cafe, lumayan bersih dan masih oke aja buat bermain anak juga.', 'tepat belang sunrise resort cafe lumayan bersih oke saja buat main anak juga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(124, 'pantainya bersih, pasilitas lengkap, mushola, wc dan kamar mandi. ada juga jasa menyewakan penginapan dan tenda camping dengan harga bervariasi', 'pantai bersih pasilitas lengkap mushola wc kamar mandi ada juga jasa inap camping harga variasi', 'positif', 'uji', '2026-04-27 22:52:46'),
(125, 'Liburan bersama keluarga besar SDN 1 Landasan Ulin Tengah, Banjarbaru. Perjalanan selama 2 jam dari Banjarbaru tak terasa saat tiba, apalagi jalan mulus seperti pipi Syahrini dengan pemandangan sepanjang jalan seindah janji para caleg... Menggunakan Bus, retribusi masuknya Rp 150.000 info petugas karena hari libur. Pantainya lumayan bersih, tp airnya keruh berlumpur (mungkin pas kebetulan kami ada yaa). Fasilitas wc/kamar mandi tersedia, ada penginapan juga bagi yg hendak bermalam. Ada banana boat dan para penjual produk khas pantai dan laut. Tersedia juga tenda besar yang di sewakan seharga Rp. 250.000 utk 1 hari full (kebetulan kami sewa). Secara keseluruhan bagus utk liburan dengan suasana kekeluargaan. SELAMAT BERLIBUR', 'libur sama keluarga besar sdn landas ulin tengah banjarbaru jalan lama jam dari banjarbaru tak asa jalan mulus seperti pipi syahrini pandang panjang jalan indah janji para caleg guna bus retribusi masuk rp info tugas karena libur pantai lumayan bersih air keruh lumpur mungkin pas betul ada ya fasilitas wc kamar mandi sedia ada inap juga bagi yang hendak malam ada banana para jual produk khas pantai laut sedia juga besar yang harga rp full betul bagus libur suasana keluarga selamat libur', 'positif', 'latih', '2026-04-27 22:52:46'),
(126, 'Banyak sekali perubahan sejak pertama kali kesini 2013. Sekarang lebih tertata rapi dan bersih.', 'banyak sekali ubah kali ke sini lebih tata rapi bersih', 'positif', 'latih', '2026-04-27 22:52:46'),
(127, 'Airx kotor,, keruh dan ada banyak serpihan kecil batu bara d pantai, jd gk berani mandi', 'airx kotor keruh ada banyak serpih kecil batu bara d pantai jadi tidak_berani mandi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(128, 'Hp saya kecebur, sangat mengasyikkan walau pantai terkesan kotor, apalagi di malam/pagi hari. Lebih bagus kalau tiap gazebo ada sumber listrik lagi. Alternatif piknik yang gak bikin bosen, kalau sampai disana waktu malam tidak perlu bayar tiket (keknya). Untuk makanan lumayan mahal, tapi enak. Rekomended lah.', 'hp saya cebur sangat asyik walau pantai kes kotor malam pagi lebih bagus kalau gazebo ada sumber listrik lagi alternatif piknik yang tidak_bikin bosen kalau sampai di sana waktu malam tidak_perlu bayar tiket kek makan lumayan mahal enak rekomended', 'negatif', 'uji', '2026-04-27 22:52:46'),
(129, 'seru, liburan di awal tahun 2026', 'asik libur awal', 'positif', 'latih', '2026-04-27 22:52:46'),
(130, 'Tempat wisata pantai paling oke ...bisa naik banana boat, bisa naik kuda keliling pantai dan msih bnyak lagi. Mana banyak pepohonan jdi gak terlalu panas. Tersedia penginapan juga klo ada yg mau nginap. Bbq juga bisa sama teman2, keluarga dll', 'pantai oke bisa naik banana bisa naik kuda keliling pantai banyak lagi banyak pohon jdi tidak_terlalu panas sedia inap juga kalau ada yang mau nginap bbq juga bisa sama teman keluarga dan lain', 'positif', 'latih', '2026-04-27 22:52:46'),
(131, 'Rekomend banget buat berswafoto, tp sayang banget disini gak bisa mandi dipantai atau main2 pasir dipinggir pantai, krna memang dari dulu air laut pantai batakan gak bisa bersih krna dibawah air laut batakan berlumpur..', 'rekomendasi banget buat berswafoto sayang banget di sini tidak_bisa mandi pantai main pasir pinggir pantai karena memang dari air laut pantai tidak_bisa bersih karena bawah air laut lumpur', 'negatif', 'latih', '2026-04-27 22:52:46'),
(132, 'Tempat wisata yang cukup bagus..cocok juga utk olahraga berkuda memanah, volly pantai dan ski air...', 'yang cukup bagus cocok juga olahraga kuda manah volly pantai ski air', 'negatif', 'latih', '2026-04-27 22:52:46'),
(133, 'Pantai batakan baru tempat wisata yg saya rekomendasikan utk dikunjungi. Pengelolaan wisata yg cukup baik, cukup bersih didukung fasilitas yg lengkap. Saran saya utk disediakan mushalla bagi pengunjung yg ingin melakukan shalat', 'pantai yang saya rekomendasi kunjung kelola yang cukup baik cukup bersih dukung fasilitas yang lengkap saran saya sedia mushalla bagi yang ingin laku shalat', 'negatif', 'latih', '2026-04-27 22:52:46'),
(134, 'Pantai Batakan Baru lebih rindang banyak pepohonan kecil, gampang memasang hammock sambil menikmati deburan angin pantai🥰 ambil posisi dekat dermaga bisa menjadi spot foto menarik, tersedia Mushola kalau mau lebih luas bisa ke Masjid dekat gerbang masuk pantai, pantai Batakan Baru bisa menjadi salah satu tujuan wisata yg nyaman untuk kumpul bersama keluarga🥰☺️ dan yg paling penting kalau liburan tolong dijaga sampahnya, dibawa pulang aja klo ga nemu tempat sampah🤭', 'pantai lebih rindang banyak pohon kecil gampang pasang hammock nikmat debur angin pantai ambil posisi dekat dermaga bisa jadi spot foto tarik sedia mushola kalau mau lebih luas bisa ke masjid dekat gerbang masuk pantai pantai bisa jadi salah satu tuju yang nyaman kumpul sama keluarga yang penting kalau libur tolong jaga sampah bawa pulang saja kalau tidak_nemu sampah', 'positif', 'latih', '2026-04-27 22:52:46'),
(135, 'Akses ke lokasi wisata udah lumayan jalannya, harga masuk tempat wisata sama harga wahananya juga masih masuk akal, tempat makan ada yg 24 jam, sama sarana penerangannya sudah bagus. Minus pengelolaan penginapan sama akses air bersih aja, pasir pantainya juga masih bisa dimaksimalkan kebersihannya.', 'akses ke lokasi sudah lumayan jalan harga masuk sama harga juga masuk akal makan ada yang jam sama sarana terang sudah bagus minus kelola inap sama akses air bersih saja pasir pantai juga bisa maksimal bersih', 'positif', 'uji', '2026-04-27 22:52:46'),
(136, 'Pelayanan kurang ramah apalagi penyewaan bangku, org sini kyknya udah dibutakan uang. Gak lagi-lagi kesini', 'layan kurang_ramah bangku orang seperti sudah buta uang tidak_lagi lagi ke sini', 'negatif', 'latih', '2026-04-27 22:52:46'),
(137, 'Bisa ditingkatkan pengelolaan dari pemda setempat karna pantai ini merupakan destinasi wisata potensial ketika weekend maupun public holiday bagi masyarakat luar kota', 'bisa tingkat kelola dari perintah karena pantai rupa destinasi potensial weekend public holiday bagi masyarakat luar kota', 'negatif', 'latih', '2026-04-27 22:52:46'),
(138, 'Ngejar sunset waktu itu, untungnya sempat karena mepet banget dari bjm. Dan tara seeee cantik itu ternyata tempat ini😍😎♥️ mayan soalnya kalo dari bjm ya bbrpa jam kan ya hii tapi keren emang🏖 berhrap semoga semua orang sadar untuk tidak membuang sampah sembrngan di tempat wisata itu aja🙏. Selamat jalan2 semuanya happy day ya 💃🏼♥️🏖🏖🏖', 'ngejar sunset waktu itu untung karena mepet banget dari banjarmasin tara seeee cantik itu nyata mayan soal kalau dari banjarmasin ya bbrpa jam kan ya hii keren memang berhrap moga semua orang sadar tidak_buang sampah sembrngan itu saja selamat jalan semua happy day ya', 'positif', 'latih', '2026-04-27 22:52:46'),
(139, 'Pantainya sangat kereeeen. Tersedia area yang luas untuk camping. Sayangnya, masih banyak sampah di sepanjang pantai.', 'pantai sangat kereeeen sedia yang luas camping sayang banyak sampah panjang pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(140, 'Cantik bat vibes nya kalau sunrise', 'cantik bat vibes kalau sunrise', 'positif', 'latih', '2026-04-27 22:52:46'),
(141, 'H+7 lebaran kesini, bener-bener ga nyangka bakal serame itu. Mau masuk aja harus antri 2 jam haha, mungkin karna saking ramenya jadi waktu masuk ga bayar dan parkir mobil juga ga bayar.', 'h lebaran ke sini benar benar tidak_nyangka serame itu mau masuk saja harus antri jam tertawa mungkin karena saking ramenya jadi waktu masuk tidak_bayar parkir mobil juga tidak_bayar', 'negatif', 'uji', '2026-04-27 22:52:46'),
(142, 'Kalo pemandangan pantai ya gitu2 aja. Tp untuk pantai yg bersih ya tentunya harus di fasilitasi jg donk.. tempat sampah atau himbauan untuk tidak buang sampah sembarangan dibatakan masih kurang bangett! Minimal kesadaran dr kita setiap pengunjung ya. Juga sepertinya perlu di beri batasan untuk tempar parkir. Selama berapa jam di batakan. Kira2 10 buah mobil terperosok dipasir yg dalam. Untuk pelengkàp liburan sdh oke penyewaan atv, kuda, banana boat, penginapan dan tempat mandi sdh banyak.', 'kalau pandang pantai ya begitu saja pantai yang bersih ya tentu harus fasilitas juga donk sampah himbauan tidak_buang sampah sembarang kurang_bangett minimal sadar dari ya juga seperti perlu beri batas tempar parkir lama jam kira buah mobil perosok pasir yang dalam pelengk p libur sudah oke atv kuda banana inap mandi sudah banyak', 'negatif', 'uji', '2026-04-27 22:52:46'),
(143, 'pantainya bagus, penginapan sama penyewaan tenda banyak, makanan banyak dan banyak permainan lainnya yg seru.. tpi sayangnya pantainya kotor sekali🙏🏻 …', 'pantai bagus inap sama banyak makan banyak banyak main lain yang asik sayang pantai kotor sekali', 'positif', 'latih', '2026-04-27 22:52:46'),
(144, 'Pantainya luas, sayangnya airnya keruh, namun utk bananaboat n atv-driving, oke sih', 'pantai luas sayang air keruh bananaboat n atv driving oke', 'positif', 'latih', '2026-04-27 22:52:46'),
(145, 'Cukup nyaman buat liburan keluarga', 'cukup nyaman buat libur keluarga', 'positif', 'latih', '2026-04-27 22:52:46'),
(146, 'Enak buat acara keluarga, tempatnya nyaman pantainya lumayan bersih dan dikelola dengan baik oleh masyarakat, banyak penginapan dan masyarakatnya ramah.', 'enak buat acara keluarga nyaman pantai lumayan bersih kelola baik masyarakat banyak inap masyarakat ramah', 'positif', 'latih', '2026-04-27 22:52:46'),
(147, 'Mau lama atau baru,, sama-sama pantai Batakan yang dari dulu sampai sekarang penataan dan pengelolaanya kurang diperhatikan. Baik itu masalah penataan parkir, kebersihan area pantai, dan tempat-tempat istirahat untuk para pengunjung. sebaiknya ada petugas yang selalu mengingatkan tentang kebersihan agar pengunjung jangan membuang sampah sembarangan, dan tempat sampah disediakan lebih banyak.', 'mau lama sama sama pantai yang dari sampai tata pengelolaanya kurang_perhati baik itu masalah tata parkir bersih pantai istirahat para baik ada tugas yang ingat tentang bersih agar jangan_buang sampah sembarang sampah sedia lebih banyak', 'negatif', 'latih', '2026-04-27 22:52:46'),
(148, 'Sayang nya batakan baru yg sekarang terlalu banyak tenda dan gajebo hampir di sepanjang bibir pantai. Sehingga menghilang kam kealamian nya', 'sayang yang terlalu banyak gajebo panjang bibir pantai hilang kam alami', 'negatif', 'latih', '2026-04-27 22:52:46'),
(149, 'Pantai favorite karna dekat dari banjarbaru 😅 selalu ramai pengunjung , wahana permainan nya cukup banyak . Ada banana boot ( Kalo gak salah 20.000 / orang Dan Maximal ber 6 ) , Kuda Kecil, Motor ATV ( Sewa nya 50.000 / 20 menit ) Kebersihan pantai nya sih kurang yaa banyak pengunjung buang sampah sembarangan, dan mungkin krn kurang petugas kebersihan nya juga . Harga jajanan nya standart, gak di Up berlebihan . Penginapan rata2 200-250 ribu / malam . Tiket masuk 5000 / orang . Parkir Mobil 5000 .', 'pantai favorite karena dekat dari banjarbaru ramai main cukup banyak ada banana boot kalau tidak_salah orang maximal ber kuda kecil motor atv menit bersih pantai kurang_ya banyak buang sampah sembarang mungkin karena kurang_tugas bersih juga harga jajan standart tidak_di up lebih inap rata ribu malam tiket masuk orang parkir mobil', 'negatif', 'uji', '2026-04-27 22:52:46'),
(150, 'Pantainya kotor & fasilitas utk pengunjung masih minim', 'pantai kotor fasilitas minim', 'negatif', 'latih', '2026-04-27 22:52:46'),
(151, 'Di sarankan jika ingin berkunjung dengan menikmati mandi di pantai maka datanglah saat musim air pasang, karena jika surut kalian akan mandi lumpur', 'saran ingin kunjung nikmat mandi pantai datang musim air pasang karena surut mandi lumpur', 'negatif', 'latih', '2026-04-27 22:52:46'),
(152, 'Salah satu destinasi wisata pantai bagus di kalsel. Glampingnya nyaman, ada wc khususnya. Bersih dan terawat.', 'salah satu destinasi pantai bagus kalsel glampingnya nyaman ada wc khusus bersih awat', 'positif', 'latih', '2026-04-27 22:52:46'),
(153, 'Bagus tmpatnya. Penginapan nya jg banyak yg di pinggir pantai, jdi bisa sambil menikmati indah nya pantai. Cuma sebagai wisatawan jangan buang sampah sembarangan ya. Tempat sampah juga udah disediakan. Jd tetap jaga kebersihannya ya, biar tetap enak dipandang.', 'bagus tmpatnya inap juga banyak yang pinggir pantai jdi bisa nikmat indah pantai hanya wisatawan jangan_buang sampah sembarang ya sampah juga sudah sedia jadi tetap jaga bersih ya biar tetap enak pandang', 'positif', 'latih', '2026-04-27 22:52:46'),
(154, 'Pantai nya bagus,rindang bikin sejuk suasana saat duduk d gazebo...saran buat pengelolaan penginapan,tempat pemandian umum dan WC nya agar d kelola dg bagus,bersih dan penerangan yg bagus,gazebo nya juga...', 'pantai bagus rindang bikin sejuk suasana duduk d gazebo saran buat kelola inap mandi umum wc agar d kelola bagus bersih terang yang bagus gazebo juga', 'positif', 'latih', '2026-04-27 22:52:46'),
(155, 'camp ke sini sengaja ngabisin orang udah pada gak liburan tahun baru dan sekolah. eh tau nya masih rame, plus banyak banget sampah di area parkiran dan pantai, jadi kita harus bersihin sendiri disekitaran camp kita😫 trus tempat sampah minim banget banget hampir gak ada klo diliat, wc umum nya masih berbayar mana ada wc yang kotor banget, jadi pilih wc yang di penginapan aja karna bersih dan tertutup. saran sih untuk tempat wisata yang dikelola pemerintah aturan nya di sediakan tempat pemandian umum dan wc gratis, trus tempat sampah nya di sediakan banyakin, kasih peringatan dilarang buang sampah sembarangan, karna sayang banget pantai nya indah tapi sampah nya luar biasa banyak banget! :( yang niat nya mau healing malah jadi zonk bangett wkwk', 'camp ke sengaja ngabisin orang sudah pada tidak_libur sekolah eh tau rame plus banyak banget sampah parkir pantai jadi harus bersihin sendiri camp terus sampah minim banget banget tidak_ada liat wc umum bayar ada wc yang kotor banget jadi pilih wc yang inap saja karena bersih tutup saran yang kelola perintah atur sedia mandi umum wc gratis terus sampah sedia banyakin kasih ingat larang buang sampah sembarang karena sayang banget pantai indah sampah luar biasa banyak banget yang niat mau healing jadi zonk bangett tertawa', 'negatif', 'latih', '2026-04-27 22:52:46'),
(156, 'Lokasi banyak pohon cemara, sangat cocok untuk pengunjung yang datang siang karna bisa berteduh dan santai disini', 'lokasi banyak pohon cemara sangat cocok yang datang siang karena bisa teduh santai di sini', 'negatif', 'latih', '2026-04-27 22:52:46'),
(157, 'salah satu tempat terbaik untuk menikmati sunset.. namun perlu ditingkatkan lagi, seperti jalan yang becek, sampahnya yang merusak pemandangan di foto dan penataan-penataan lainnya', 'salah satu baik nikmat sunset perlu tingkat lagi seperti jalan yang becek sampah yang rusak pandang foto tata tata lain', 'negatif', 'latih', '2026-04-27 22:52:46'),
(158, 'hihihihi seruuuu bisa liburan kesini', 'hihihihi seruuuu bisa libur ke sini', 'positif', 'latih', '2026-04-27 22:52:46'),
(159, 'Pantai ini sangat ramai apalagi kalau weekend. Sangat ramai namun tidak ada pohon untuk bernaung. Untuk lokasi parkir sangat luas disepanjang pantai. Cocok untuk tempat camping dan pengunjung yang ini berlibur bersama keluarga. Untuk spot foto juga ada. Sangat direkomendasikan untuk yang ini healing.', 'pantai sangat ramai kalau weekend sangat ramai tidak_ada naung lokasi parkir sangat luas panjang pantai cocok camping yang libur sama keluarga spot foto juga ada sangat rekomendasi yang healing', 'positif', 'uji', '2026-04-27 22:52:46'),
(160, 'Recomended datang pagi hari, klo lewat siang airnya sedikit surut, tepian pantainya lebar dan bersih,,', 'recomended datang pagi kalau lewat siang air sedikit surut tepi pantai lebar bersih', 'negatif', 'latih', '2026-04-27 22:52:46'),
(161, 'Lumayan bagus tapi untuk tempat dan variasi makanan kurang banyak', 'lumayan bagus variasi makan kurang_banyak', 'positif', 'latih', '2026-04-27 22:52:46'),
(162, 'Pantai bersih, lumayan private, pengurus pantai juga humble dan baik baik semuanya. Fasilitas lengkap, pohon rindang. Semoga tetap terjaga💪', 'pantai bersih lumayan private urus pantai juga humble baik baik semua fasilitas lengkap pohon rindang moga tetap jaga', 'negatif', 'latih', '2026-04-27 22:52:46'),
(163, 'cantik banget, bersih, ramai, untuk tiket masuk kurang tau sih, soalnya waktu itu rame-rame bareng keluarga. cocok pokoknya untuk familytime', 'cantik banget bersih ramai tiket masuk kurang_tau soal waktu itu rame rame bareng keluarga cocok pokok familytime', 'negatif', 'uji', '2026-04-27 22:52:46'),
(164, 'awal tahun 2025, gak nyangka pantai nya se kotor ini penuh dengan sampah.. semoga pihak yang berwenang bisa menemukan cara buat penanggulangan sampah nya biar ga begini lagi.', 'awal tidak_nyangka pantai se kotor penuh sampah moga pihak yang wenang bisa temu buat tanggulang sampah biar tidak_begini lagi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(165, 'Bagus, Mayan bersih makanan penginapannya ok, tp sbting banyu nya rigat alias keruuuuuhhhh ..', 'bagus mayan bersih makan inap oke sbting air kotor alias keruuuuuhhhh', 'positif', 'latih', '2026-04-27 22:52:46'),
(166, 'Pantai yg paling dekat dari banjarmasin.waktu kesana air laut keruh dan pesisir juga agak kotor. Ada penyewaan ATV,naik kuda,tenda dan peralatan camping. Waktu mau sholat ashar saya wudhu di tempat penginapan dekat pantai,karena musholanya jauh saya ditawari sholat ditempat ibunya saja,masyaAllah Alhamdulillah jadi tidak perlu berjalan jauh.', 'pantai yang dekat dari banjarmasin waktu kesana air laut keruh pesisir juga agak kotor ada atv naik kuda alat camping waktu mau sholat ashar saya wudhu inap dekat pantai karena musholanya jauh saya tawar sholat saja masyaallah alhamdulillah jadi tidak_perlu jalan jauh', 'negatif', 'latih', '2026-04-27 22:52:46'),
(167, 'Puas disini, selain ada penginapan nyari makan juga enak. Pantai nya bersih walaupun seperti warna laut kebanyakan di Kalimantan tidak biru. Hati hati sama kotoran kuda 😂', 'puas di sini ada inap cari makan juga enak pantai bersih seperti warna laut banyak kalimantan tidak_biru hati hati sama kotor kuda', 'netral', 'latih', '2026-04-27 22:52:46'),
(168, 'Tempat sangat rekomended. Sangat nyaman, sejuk, bersih, banyak tempat untuk berteduh. ada jua jasa sewa tenda yang luas & penginapan. WC dan kamar bilas tersedia cukup memadai. Minusnya mushola dekat pantai terlihat kurang terawat dan air untuk wudhu sering tidak ada.', 'sangat rekomended sangat nyaman sejuk bersih banyak teduh ada juga jasa yang luas inap wc kamar bilas sedia cukup pada minus mushola dekat pantai lihat kurang_awat air wudhu sering tidak_ada', 'positif', 'latih', '2026-04-27 22:52:46'),
(169, 'Sangat ramai,macet arah pintu masuk,apalagi musim liburan seperti ini', 'sangat ramai macet arah pintu masuk musim libur seperti', 'negatif', 'uji', '2026-04-27 22:52:46'),
(170, 'Pesisir pantai nya panjang, tempat parkir luas, banyak tersedia Toilet dan kamar mandi, banyak gajebo nya juga, banyak penyewaan ATV, Banana Boat dan Tenda Tenda untuk acara keluarga dan gathering... Keamanan, kebersihan terjaga...', 'pesisir pantai panjang parkir luas banyak sedia toilet kamar mandi banyak gajebo juga banyak atv banana acara keluarga gathering aman bersih jaga', 'positif', 'latih', '2026-04-27 22:52:46'),
(171, 'Rame bngt pantainy, sayang ga ada yg ngatur parkir jdi parkirnya berantakan. Bnyk yg buang sampah sembarangan juga, pdhal udh disefiain yempat sampah', 'rame banget pantainy sayang tidak_ada ngatur parkir jdi parkir beranta banyak yang buang sampah sembarang juga pdhal sudah disefiain yempat sampah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(172, 'Pantainya bagus. Ada penginapan walau menurut saya agak mahal. Ada jualan suvenir. Ada jual kerupuk, ikan kering, amplang, ada warungnya juga. Ada tenda2, ada motor2an gitu yang bisa di sewa, kamar mandinya bayar, tapi kalau mau cuci tangan/kaki aja gratis di luar. Bisa pesan makanan di situ juga. Ada acil2 jualan kerupuk, amplang, udang wadi (?), sawo, dll keliling. Ada kaya delman gitu. Ada speeadboat. Sayang jalan masuknya menurut aku kurang enak.', 'pantai bagus ada inap walau turut saya agak mahal ada jual suvenir ada jual kerupuk ikan kering amplang ada warung juga ada ada motor an begitu yang bisa kamar mandi bayar kalau mau cuci tangan kaki saja gratis luar bisa pesan makan situ juga ada acil jual kerupuk amplang udang wadi sawo dan lain keliling ada kaya delman begitu ada speeadboat sayang jalan masuk turut saya kurang_enak', 'netral', 'latih', '2026-04-27 22:52:46'),
(173, 'Sekarang pantainya makin kereeen, terus ada fotografernya lagi buat mengabadikan momennya yang harganya terjangkau baaanget', 'pantai makin kereeen terus ada fotografer lagi buat abadi momen yang harga jangkau baaanget', 'positif', 'latih', '2026-04-27 22:52:46'),
(174, 'Banyak penginapan ,tempat bersih, nyaman..pemandangannya indah dan pelayanan org sekitar ramah', 'banyak inap bersih nyaman pandang indah layan orang ramah', 'positif', 'latih', '2026-04-27 22:52:46'),
(175, 'Pengalaman aku saat di Batakan Baru yaaa senang banget .. Pantai ya luas banget... Tempat nya juga bagus .. Disana tersedia penginapan juga bagi yang mau nginap... Tersedia tempat mandi juga buat bersih2.. untuk harga 2.000-5.000.. Yang jualan juga banyak ... ada berbagai ikan kering khas batakan ... Atv dan lain lain', 'alam saya ya senang banget pantai ya luas banget juga bagus di sana sedia inap juga bagi yang mau nginap sedia mandi juga buat bersih harga yang jual juga banyak ada ikan kering khas atv lain lain', 'positif', 'latih', '2026-04-27 22:52:46'),
(176, 'Suasana yang lumayan nyaman untuk pantai yang tidak terlalu jauh dari pusat Kota Banjarmasin', 'suasana yang lumayan nyaman pantai yang tidak_terlalu jauh dari pusat kota banjarmasin', 'positif', 'latih', '2026-04-27 22:52:46'),
(177, 'Bagus, luas, cocok untuk liburan, banyak pohon jadi nyaman buat neduh, tempat pemandian banyak, penginapan juga ada, tapi seperti biasa airnya keruh kek m*lo :((', 'bagus luas cocok libur banyak pohon jadi nyaman buat neduh mandi banyak inap juga ada seperti biasa air keruh kek m lo', 'negatif', 'latih', '2026-04-27 22:52:46'),
(178, 'Area lumayan bagus, fasitas temoat sampah masih perlu di tambah. Tempat ibadah ada, walau berada di area wisata', 'lumayan bagus fasitas temoat sampah perlu tambah ibadah ada walau ada', 'positif', 'latih', '2026-04-27 22:52:46'),
(179, 'Pantainya panjang, bersih, fasilitas mandi dan wc lengkap, warung lengkap, souvenir ada. Pokoknya rekomended untuk wisata pantai', 'pantai panjang bersih fasilitas mandi wc lengkap warung lengkap souvenir ada pokok rekomended pantai', 'positif', 'latih', '2026-04-27 22:52:46'),
(180, 'Pengalaman camping yang sangat nyaman, dengan suasana yang tenang di hari sabtu', 'alam camping yang sangat nyaman suasana yang tenang sabtu', 'positif', 'latih', '2026-04-27 22:52:46'),
(181, 'Pantainya indah, suasananya aman, warganya ramah. Tinggal pengunjungnya yg harus jaga kebersihan.', 'pantai indah suasana aman warga ramah tinggal yang harus jaga bersih', 'positif', 'uji', '2026-04-27 22:52:46'),
(182, 'Tempat nya bersih dan banyak jasa sewa motor trail dan mobil mobilan. Ada juga kuda.. di air ada banana boat.... bagi yg mau jiarah ada klotok atau perahu buat menuju ke pulau Datu...', 'bersih banyak jasa motor trail mobil mobil ada juga kuda air ada banana bagi yang mau jiarah ada perahu perahu buat tuju ke pulau datu', 'positif', 'latih', '2026-04-27 22:52:46'),
(183, 'Pantainya cukup bagus, penerimaan penduduk setempat sangat ramah, fasilitas pantai cukup baik', 'pantai cukup bagus terima duduk sangat ramah fasilitas pantai cukup baik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(184, 'tempat yang cocok liburan dengan keluarga', 'yang cocok libur keluarga', 'positif', 'latih', '2026-04-27 22:52:46'),
(185, 'Pantai Batakan sekarang luar biasa, fasilitas komplit tinggal bawa baju & badan saja.', 'pantai luar biasa fasilitas komplit tinggal bawa baju badan saja', 'negatif', 'uji', '2026-04-27 22:52:46'),
(186, 'Termasuk pantai yang bagus dibanding pantai sekitar-sekitarnya, hanya saja untuk area glamping saya rasa masih kurang untuk tendanya jauh dari kata banyak dan harus reservasi jauh-jauh hari. Juga jalan sebelum pintu gerbang memasuki pantai harus jadi sorotan bagi dinas pariwisata terkait, semoga lebih bagus kedepannya dan semakin memajukan pendapatan masyarakat daerahnya', 'masuk pantai yang bagus banding pantai hanya saja glamping saya rasa kurang_untuk jauh dari kata banyak harus reservasi jauh jauh juga jalan belum pintu gerbang pasuk pantai harus jadi sorot bagi dinas pariwisata kait moga lebih bagus makin maju dapat masyarakat daerah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(187, 'Mantap, minusnya Jauh, WC & KM bayar', 'mantap minus jauh wc km bayar', 'negatif', 'latih', '2026-04-27 22:52:46'),
(188, 'Bagus ngak fotonya? Kamera canon .... nginap nya mahal, bawa tenda sendiri murah, paling minjam kamar mandi.. wkwkwk', 'bagus ngak foto kamera canon nginap mahal bawa sendiri murah minjam kamar mandi tertawa', 'netral', 'latih', '2026-04-27 22:52:46'),
(189, 'Bayar parkir mahal 10rb, tp pas masuk kedlm nyari parkir susah karna kebanyakan gajebo, tenda, dan warung dadakan. Enakan ky dl, bebas parkir dmana aja terus gelar tikar, gak perlu keluarin uang buat sewa gajebo', 'bayar parkir mahal ribu pas masuk kedlm cari parkir susah karena banyak gajebo warung dada enak ky bebas parkir dmana saja terus gelar tikar tidak_perlu keluarin uang buat gajebo', 'negatif', 'latih', '2026-04-27 22:52:46'),
(190, 'Sunset nyaa kren bangett, tempat nyaa nyamann bnget untuk healing dari jenuh nyaa kota. 😍 …', 'sunset nyaa kren bangett nyaa nyamann bnget healing dari jenuh nyaa kota', 'negatif', 'latih', '2026-04-27 22:52:46'),
(191, 'Sedikit kecewa dengan wahana ini, waktunya terlalu singkat cuman satukali putaran kecil sudah berhenti, apakah karena hari besar sehingga waktunya dipersingkat, tolong kedepannya diperbaiki lagi agar pelanggan tidak kecewa', 'sedikit kecewa waktu terlalu singkat hanya satukali putar kecil sudah henti karena besar waktu singkat tolong baik lagi agar langgan tidak_kecewa', 'negatif', 'latih', '2026-04-27 22:52:46'),
(192, 'Tempat buat santai bareng teman2, berenang, naik banana boat. Seru pokok na', 'buat santai bareng teman renang naik banana asik pokok na', 'positif', 'latih', '2026-04-27 22:52:46'),
(193, 'Masuk perorg 5k,parkir 5k,cuman pang naik delman 50 k utk 4 org,naik afv 50k utk 20 menit naik kuda 40k 2 org,mahal di wahana2x', 'masuk perorg k parkir k hanya pang naik delman k orang naik afv k menit naik kuda k orang mahal x', 'negatif', 'latih', '2026-04-27 22:52:46'),
(194, 'Lumayan lah ,, kondisi pantai sgt baik, hanya perlu peningkatan pengelolaan sampah /limbah 😊🙏 …', 'lumayan kondisi pantai sangat baik hanya perlu tingkat kelola sampah limbah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(195, 'Sunset Pantai Batakan tidak pernah gagal', 'sunset pantai tidak_pernah gagal', 'negatif', 'latih', '2026-04-27 22:52:46'),
(196, 'Seperti umumnya pantai wisata yang rame... Fasilitas penunjangnya sudah cukup lengkap. Ada mushola, toilet-toilet berbayar di warung2 yang ada di sepanjang pantai. Ada beberapa penginapan dan penyewaan tenda juga. Pulangnya bawa oleh-oleh seafood kering aja. Iwak telang, Senangin, Kakap, Cumi... Bebas pilih. Sayang masih banyak sampah berserak, mostly kemasan plastik/styrofoam beragam rupa sih. Tp sy gak foto tumpukan2 sampahnya, berharap pas ke sinj lagi sudah bersih, alias sudah ada intervensi pihak berwenang untuk mendukung pengelolaan sampah di sini. Produksi sampahnya pasti lumayan setiap hari karena ini pantai wisata yg ramai. Lagian pengunjung bayar 10rb, termasuk restribusi kebersihan 1000per orang di harga karcis masuk...', 'seperti umum pantai yang rame fasilitas tunjang sudah cukup lengkap ada mushola toilet toilet bayar warung yang ada panjang pantai ada inap juga pulang bawa seafood kering saja iwak telang senangin kakap cumi bebas pilih sayang banyak sampah serak mostly kemas plastik styrofoam agam rupa saya tidak_foto tumpu sampah harap pas ke sinj lagi sudah bersih alias sudah ada intervensi pihak wenang dukung kelola sampah produksi sampah pasti lumayan karena pantai yang ramai lagi bayar ribu masuk restribusi bersih orang harga karcis masuk', 'negatif', 'latih', '2026-04-27 22:52:46'),
(197, 'Pantainya bersih, banyak yg menyediakan tenda dan tikar. Pas lah kalau mau bawa anak² bermain di pantai. Bisa juga kalau mau nginap ada yg menyediakan tempatnya.', 'pantai bersih banyak yang sedia tikar pas kalau mau bawa anak main pantai bisa juga kalau mau nginap ada yang sedia', 'positif', 'uji', '2026-04-27 22:52:46'),
(198, 'Salah satu tempat distinasi wisata wajib dikunjungi....jalan aspal mulai dibenahi, banyak tenda2 yg disewakan...pantai bagus ....', 'salah satu distinasi wajib kunjung jalan aspal mulai benah banyak yang pantai bagus', 'netral', 'latih', '2026-04-27 22:52:46'),
(199, 'Wajib berkunjung d sini Bagus bngt🌼😍😍😍😍😍', 'wajib kunjung d bagus banget', 'positif', 'latih', '2026-04-27 22:52:46');
INSERT INTO `ulasan` (`id`, `teks_asli`, `teks_clean`, `label`, `tipe_data`, `tanggal_input`) VALUES
(200, 'Sebuah pantai wisata yang cukup luas, sangat cocok untuk liburan bersama keluarga maupun pasangan, terdapat wahana permainan yg dapat dinikmati, diantaranya naik kapal, motor, kuda, dan banyak lagi wahana lainnya, banyak jajanan makanan yang djual dsini, terdapat tenda/kemah yang dapat disewa, harga mulai 75.000 sampai 125.000 / malam, harga tergantung besar kecilnya. Waspada bermalam dipinggir pantai karena pantai sewaktu-waktu bisa pasang/bertambah dalam. Ada penginapan khusus juga disediakan.', 'buah pantai yang cukup luas sangat cocok libur sama keluarga pasang dapat main yang dapat nikmat antara naik kapal motor kuda banyak lagi lain banyak jajan makan yang djual dsini dapat kemah yang dapat harga mulai sampai malam harga gantung besar kecil waspada malam pinggir pantai karena pantai waktu waktu bisa pasang tambah dalam ada inap khusus juga sedia', 'positif', 'latih', '2026-04-27 22:52:46'),
(201, 'Sekarang jadi semakin kurang bagus. Di karena kan bnyak nya tenda di sepanjang pesisir pantai yg untuk di sewakan. Jdi kliatan tidak asri lgi.', 'jadi makin kurang_bagus karena kan banyak panjang pesisir pantai yang jdi kliatan tidak_asri lgi', 'netral', 'latih', '2026-04-27 22:52:46'),
(202, 'Nyaman,Aman & Murah... Penduduk sekitar pun ramah tamah.. Sooo pertahankan & kalau bisa tambah lagi untuk tanaman pohon,biar tambah teduh.. Ini sdh kesekian kali saya k\'batakan baru..', 'nyaman aman murah duduk pun ramah tamah sooo tahan kalau bisa tambah lagi tanam pohon biar tambah teduh sudah sekian kali saya k', 'negatif', 'latih', '2026-04-27 22:52:46'),
(203, 'Pemandangan Bagus, pantai kurang Bersih, fasilitas umum butuh perawatan.', 'pandang bagus pantai kurang_bersih fasilitas umum butuh awat', 'positif', 'latih', '2026-04-27 22:52:46'),
(204, 'Jika ada hari-hari besar maka anda akan terjebak macet di jalan karena banyaknya pengunjung..HTM hari besar 10ribu didalam sudah tidak di pungut biaya lagi untuk parkir,kecuali anda menyewa ATV,Bananaboat,atau menaiki kuda.sekarang sudah sangat bagus karena di kelola pemerintah..', 'ada besar anda jebak macet jalan karena banyak htm besar ribu dalam sudah tidak_di pungut biaya lagi parkir kecuali anda atv bananaboat naik kuda sudah sangat bagus karena kelola perintah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(205, 'sudah cukup bersih menurutku cuman ada beberapa sampah masih berserakan di tepi pantai, selebihnya oke, asik loh juga ada banana boat nya', 'sudah cukup bersih turut hanya ada sampah sera tepi pantai lebih oke asik juga ada banana', 'negatif', 'latih', '2026-04-27 22:52:46'),
(206, 'Great place to visit 😆 Tempat parkir deket banget sama pantai.. Jadi kalo ban kendaraannya mumpuni bisa dibawa sampe ke area leyeh2.. Tapi kalo ga lumayan bisa nyangkut di pasir.. Ada penyewaan ATV, terpal, karpet, atau kursi pantai.. Ada banana boat, naik kuda, sama penyewaan ban buat anak2 kecil (gatau mungkin ada juga buat orang dewasa).. Warung berjejer aja di area pantai.. Dari snack, makanan, sampe kelapa ada.. Suka ada penjaja yang jual amplang, sawo (in my case), cumi/ikan asin, sampe kerupuk ikan.. Airnya lumayan bersih.. Yaa ijo2 keruh gitu lah.. Tapi compare to others dia lumayan bersih.. Bisa buat salah satu pilihan wisata buat keluarga, pasangan, temen, atau mau santai sendiri juga bisa.. Beberapa ada yang camping juga.. PS. One of the greatest thing here adalah ADA TEMPAT SAMPAHNYA 😆 (kadang di beberapa tempat wisata suka susah nyari tempat sampah soalnya 😅) Update: balik lagi ke sini bulan desember.. Sesuai info warlok pas bulan desember kondisi airnya cenderung lebih kotor.. Warnanya bener2 coklat.. Jadi kalo mau ke sini mungkin better sekitar tengah tahun..', 'great place to visit parkir dekat banget sama pantai jadi kalau ban kendara mumpuni bisa bawa sampe ke leyeh kalau tidak_lumayan bisa nyangkut pasir ada atv terpal karpet kursi pantai ada banana naik kuda sama ban buat anak kecil gatau mungkin ada juga buat orang dewasa warung jejer saja pantai dari snack makan sampe kelapa ada suka ada jaja yang jual amplang sawo in my case cumi ikan asin sampe kerupuk ikan air lumayan bersih ya ijo keruh begitu compare to others dia lumayan bersih bisa buat salah satu pilih buat keluarga pasang temen mau santai sendiri juga bisa ada yang camping juga ps one of the greatest thing here ada sampah kadang suka susah cari sampah soal update balik lagi ke bulan desember sesuai info warlok pas bulan desember kondisi air cenderung lebih kotor warna benar keruh jadi kalau mau ke mungkin better tengah', 'netral', 'latih', '2026-04-27 22:52:46'),
(207, 'Pantai Batakan Baru nyaman untuk suasana santai, hanya pasir kotor banyak sampah yang berserakan, pembersihan mohon di tingkat kan lagi', 'pantai nyaman suasana santai hanya pasir kotor banyak sampah yang sera bersih mohon tingkat kan lagi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(208, 'After 1years balik kesini berubah sangat banyak ya travellers,dulu masih sepi dan sekarang wahana dan fasilitas udah lengkap tentu rameee bangett kalo weekend.. Just info HTM 5000,parkir 5000 yang jualan makanan banyak 😁 tapi yang sangat memprihatinkan pantainya kotor banyak sampah plastik,popok etc yook travellers dimanapun kalian pergi selalu jaga kebersihan,kalo ga ada tempat sampah masukin plastik bawa balik.', 'after years balik ke sini ubah sangat banyak ya travellers sepi fasilitas sudah lengkap tentu rameee bangett kalau weekend just info htm parkir yang jual makan banyak yang sangat prihatin pantai kotor banyak sampah plastik popok etc yook travellers pergi jaga bersih kalau tidak_ada sampah masukin plastik bawa balik', 'negatif', 'latih', '2026-04-27 22:52:46'),
(209, 'Pantai yang sangat indah, cocok buat liburan bareng keluarga dan teman2. Rekomended buat kalian yang mau healing', 'pantai yang sangat indah cocok buat libur bareng keluarga teman rekomended buat yang mau healing', 'positif', 'latih', '2026-04-27 22:52:46'),
(210, 'Sangat rekomend sekali pantai ini d jadikan sbagai alternatif utk refreshing mengisi waktu liburan kita utk menghilangkan stress. Tempatnya yg lumayan nyaman dgn fasilitas sarana hiburan yg lumayan jg psti tmpt ini akan membuat kalian meninggalkan kesan tersendiri. Saran himbauan dr saya utk senantiasa kita dengan kesadaran masing2 utk tetap bs menjaga kebersihan lingkungan, salah satu d antaranya yg utama adalah dgn tdk membuang sampah sembarangan', 'sangat rekomendasi sekali pantai d jadi sbagai alternatif refreshing isi waktu libur hilang stress yang lumayan nyaman fasilitas sarana hibur yang lumayan juga psti tmpt buat tinggal kesan sendiri saran himbauan dari saya senantiasa sadar tetap bs jaga bersih lingkung salah satu d antara yang utama tidak_buang sampah sembarang', 'negatif', 'uji', '2026-04-27 22:52:46'),
(211, 'Pantai yang banyak fasilitasnya', 'pantai yang banyak fasilitas', 'negatif', 'latih', '2026-04-27 22:52:46'),
(212, 'Jalan menuju pantai mulus, Fasilitas lengkap, tempatnya enak teduh karna banyak pohon. Saat weekend sangat ramai sekali.', 'jalan tuju pantai mulus fasilitas lengkap enak teduh karena banyak pohon weekend sangat ramai sekali', 'negatif', 'latih', '2026-04-27 22:52:46'),
(213, 'Kami kasini pas karuh. Dan mus hujan. Jadi kurang optimal Tapi cocok haja pang gasan hiburan keluarga. Semoga bisa ditingkatkan', 'kasini pas karuh mus hujan jadi kurang_optimal cocok haja pang gas hibur keluarga moga bisa tingkat', 'positif', 'latih', '2026-04-27 22:52:46'),
(214, 'jauh² saya dari muara teweh hanya untuk menikmati angin segar dan hamparan pantai yg sangat luas,pokoknya puas', 'jauh saya dari muara teweh hanya nikmat angin segar hampar pantai yang sangat luas pokok puas', 'negatif', 'latih', '2026-04-27 22:52:46'),
(215, 'Bayar masuk dewasa 4.500 anak kecil tidak dihitung, ATV 50 rb 20 menit , gajebo atau tenda 150 , kuda 30 rb 1 kali keliling , carter perahu kepulau datu 150 rb', 'bayar masuk dewasa anak kecil tidak_hitung atv ribu menit gajebo kuda ribu kali keliling carter perahu pulau datu ribu', 'negatif', 'latih', '2026-04-27 22:52:46'),
(216, 'Viewnya bagus Makanan murah Penginapan murah Yang kurang cuma kebersihan. Semoga semua sama2 tetap menjaga kebersihan', 'viewnya bagus makan murah inap murah yang kurang_hanya bersih moga semua sama tetap jaga bersih', 'positif', 'uji', '2026-04-27 22:52:46'),
(217, 'Sekarang banyak penginapan dan kamar mandi yg tersedia.', 'banyak inap kamar mandi yang sedia', 'positif', 'latih', '2026-04-27 22:52:46'),
(218, 'Sebenarnya sangat bagus, hanya sayang kemerduan debur ombak \"dokotori\" oleh orang-orang egois. Semoga pengelola bisa menertibkan', 'benar sangat bagus hanya sayang merdu debur ombak dokotori orang orang egois moga kelola bisa tertib', 'negatif', 'latih', '2026-04-27 22:52:46'),
(219, 'Sunsetnya bagus dan jangan lupa kalau kesini beli ikan kering tawar enak seperti kerupuk', 'sunset bagus jangan_lupa kalau ke sini beli ikan kering tawar enak seperti kerupuk', 'negatif', 'latih', '2026-04-27 22:52:46'),
(220, 'Air lautnya kotor dan berlumpur Karcis masuk dewasa 10.000/orang Parkir 10.000/mobil Sewa gazebo 250.000/malam Sewa ATV 50.000/25 menit', 'air laut kotor lumpur karcis masuk dewasa orang parkir mobil gazebo malam atv menit', 'negatif', 'latih', '2026-04-27 22:52:46'),
(221, 'pantai bagus penginapan ada tpi syg pihak pengelolah pantai tidak perhatian dengan smpah di pantai', 'pantai bagus inap ada syg pihak elo pantai tidak_perhati smpah pantai', 'positif', 'latih', '2026-04-27 22:52:46'),
(222, 'Ke pantai atau tempat rekreasi wisata alam lainnya memang sebaiknya di lakukan di luar hari libur agar bisa menikmati suasana maupun fasilitas nya. Secara umum pantai nya bagus, tempat parkir mobil dekat dengan tempat drop barang. Hanya saja kemarin kesini pas liburan sekolah, jd volume pengunjung mengakibatkan tumpukan sampah dan manusia yg banyak. Fasilitas penunjang nya (toilet, kmr mandi, musholla dan penginapan) sdh banyak. Bisa bisa memilih aj lagi.', 'ke pantai rekreasi alam lain memang baik laku luar libur agar bisa nikmat suasana fasilitas umum pantai bagus parkir mobil dekat drop barang hanya saja kemarin ke sini pas libur sekolah jadi volume akibat tumpu sampah manusia yang banyak fasilitas tunjang toilet kmr mandi musholla inap sudah banyak bisa bisa pilih aj lagi', 'netral', 'latih', '2026-04-27 22:52:46'),
(223, 'Lumayan lahh. Tpi lebih bagus pantai turki( tungkaran kiri ) 🤩', 'lumayan lahh lebih bagus pantai turki tungkaran kiri', 'netral', 'uji', '2026-04-27 22:52:46'),
(224, 'Bagus tp masih kurang perhatuan dari pemerintah setempat jd fasilitanya masih kurang juga, secara keseluruhan bagus dan lumayan bersih juga', 'bagus kurang_perhatuan dari perintah jadi fasilitanya kurang_juga bagus lumayan bersih juga', 'positif', 'latih', '2026-04-27 22:52:46'),
(225, 'Cocok buat wisata keluarga', 'cocok buat keluarga', 'positif', 'latih', '2026-04-27 22:52:46'),
(226, 'Pantai nya bagus,kesadaran diri individu saja untuk menjaga kebersihan,usahakan buang sampah pada tempat nya krn sudah disediakan bak sampah besar Bayar masuk 5000 per org,ada permainan banana boat,ATV,toilet dan kamar mandi nya banyak', 'pantai bagus sadar diri individu saja jaga bersih usaha buang sampah pada karena sudah sedia bak sampah besar bayar masuk orang ada main banana atv toilet kamar mandi banyak', 'negatif', 'latih', '2026-04-27 22:52:46'),
(227, 'banyak penginapan dengan fasilitas kipas angin dan kasur, cuma agak susah untuk ke toilet, krn airnya agak keruh dan sedikit asin, klo nginap sebaiknya pilih kamar yg belakang, krn kamar paling depan terganggu dengan keributan di pantai', 'banyak inap fasilitas kipas angin kasur hanya agak susah ke toilet karena air agak keruh sedikit asin kalau nginap baik pilih kamar yang belakang karena kamar ganggu ribut pantai', 'negatif', 'uji', '2026-04-27 22:52:46'),
(228, 'Pantai nya bersih, ada penginapan, WC dan kamar mandi lengkap. Cocok untuk liburan', 'pantai bersih ada inap wc kamar mandi lengkap cocok libur', 'positif', 'latih', '2026-04-27 22:52:46'),
(229, 'Salah satu destinasi wisata pantai yang wajib dikunjungi. Yang suka ngecamp juga bisa disini. Jadi tunggu apalagi, buruan berkunjung di Pantai Batakan Baru.', 'salah satu destinasi pantai yang wajib kunjung yang suka ngecamp juga bisa di sini jadi tunggu buru kunjung pantai', 'negatif', 'latih', '2026-04-27 22:52:46'),
(230, 'Banyak orng kampung pungli,kita ngecamp sering di mintain uang', 'banyak orang kampung pungli ngecamp sering mintain uang', 'negatif', 'latih', '2026-04-27 22:52:46'),
(231, 'Banyak tersedia penginapan low budget - high', 'banyak sedia inap low budget high', 'positif', 'latih', '2026-04-27 22:52:46'),
(232, 'Sangat nyaman dan tempat yang bagus untuk camp bersama keluarga. Teman dan pasangan', 'sangat nyaman yang bagus camp sama keluarga teman pasang', 'positif', 'latih', '2026-04-27 22:52:46'),
(233, 'Salah satu tempat wisata yang recommended untuk rekreasi bersama keluarga, pasir pantainya bersih, banyak penginapan juga di sini, fasilitas ok lah ya', 'salah satu yang recommended rekreasi sama keluarga pasir pantai bersih banyak inap juga fasilitas oke ya', 'positif', 'latih', '2026-04-27 22:52:46'),
(234, 'Pantai yg cukup bagus dan akses menuju kelokasi jalannya bagus cuma pas naikan mau antri tiket masuk aja jalannya lumaian kurang enak. Untuk kondisi pantai bolehlah', 'pantai yang cukup bagus akses tuju lokasi jalan bagus hanya pas naik mau antri tiket masuk saja jalan lumai kurang_enak kondisi pantai boleh', 'positif', 'latih', '2026-04-27 22:52:46'),
(235, 'Sebuah pilihan wisata pantai buat Anda yang senang travelling. Di sini akan Anda temukan warung tradisional khas kalsel dan juga Anda pasti bertemu para pedagang dengan bawaannya masing-masing, Sangat menyenangkan berlibur di sini.', 'buah pilih pantai buat anda yang senang travelling anda temu warung tradisional khas kalsel juga anda pasti temu para dagang bawa sangat senang libur', 'negatif', 'latih', '2026-04-27 22:52:46'),
(236, 'Pantai nya bebagus, mungkin kebersihan hrs ditinggatkan lg 😉', 'pantai bebagus mungkin bersih harus ditinggatkan lagi', 'negatif', 'uji', '2026-04-27 22:52:46'),
(237, 'Bagus, banyak pohon pinus buat neduh ato gantung hammock, da banyak jg yg mnginap....', 'bagus banyak pohon pinus buat neduh ato gantung hammock da banyak juga yang mnginap', 'negatif', 'latih', '2026-04-27 22:52:46'),
(238, 'Pantainya baguss banget cuma pungli nye geloo banyak banget masa masang tenda bayar dibilang buat biaya kebersihan dan sewa tempat, mana pantainya ga secakep dulu banyak banget tenda tenda jadi ga enjoy banget nikmatin suasana pantai. Masalah pungli tolong segera diperbaiki deh buat pemerintah', 'pantai baguss banget hanya pungli geloo banyak banget masa masang bayar bilang buat biaya bersih pantai tidak_cakep banyak banget jadi tidak_enjoy banget nikmatin suasana pantai masalah pungli tolong segera baik saja buat perintah', 'negatif', 'latih', '2026-04-27 22:52:46'),
(239, 'Pantai yang bagus dan menarik. Ombak yg tidak terlalu besar, aman bagi anak-anak untuk bermain. Datang ke sini di hari Minggu pagi.', 'pantai yang bagus tarik ombak yang tidak_terlalu besar aman bagi anak anak main datang ke minggu pagi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(240, 'Banyak spot untuk swafoto,pantainya bersih,bisa untuk camping 👍👍 …', 'banyak spot swafoto pantai bersih bisa camping', 'netral', 'latih', '2026-04-27 22:52:46'),
(241, 'Tambah bagus, semoga dinas pariwisata konsisten untuk membenahi tempat wisata ini.', 'tambah bagus moga dinas pariwisata konsisten benah', 'positif', 'uji', '2026-04-27 22:52:46'),
(242, 'Cocok buat camping rame-rame, bagus juga lokasinya buat foto2 😊', 'cocok buat camping rame rame bagus juga lokasi buat foto', 'positif', 'uji', '2026-04-27 22:52:46'),
(243, 'Kalo ingin pergantian taun nya di pantai, cttn 3 hari sebelum, harus sudah di lokasi,', 'kalau ingin ganti taun pantai cttn belum harus sudah lokasi', 'negatif', 'latih', '2026-04-27 22:52:46'),
(244, 'glamping tersedia', 'glamping sedia', 'positif', 'latih', '2026-04-27 22:52:46'),
